package org.pumpfoil.app

// Teams & Events (01.11.2026, docs/TEAMS.md „Native-Port"): alle Texte `team.*` plus `sd.avgHrFoil`/`sd.avgHrGesamt`,
// aus web/src/i18n/locales/*.ts uebernommen (alle 18 Sprachen, wortgleich mit dem Web). I18n.t fragt diese Tabelle
// direkt nach NEU; fehlt ein Schluessel, gilt die Bruecke wie im Web (gsw/de-AT -> de, pt-PT -> pt), dann Englisch.
// Je Sprache eine eigene Funktion: als EIN mapOf waeren es ~5000 Paare und damit ueber der 64-KB-Grenze je Methode.
// Platzhalter wie im Web: {name}, {n} … — der Aufrufer ersetzt sie mit .replace.

private val TEAMS_BRUECKE = mapOf("gsw" to "de", "de-AT" to "de", "pt-PT" to "pt")

internal val TEAMS_TEXTE: Map<String, Map<String, String>> by lazy {
    mapOf(
        "de" to texteDE(),
        "gsw" to texteGSW(),
        "de-AT" to texteDEAT(),
        "en" to texteEN(),
        "fr" to texteFR(),
        "it" to texteIT(),
        "es" to texteES(),
        "fi" to texteFI(),
        "nl" to texteNL(),
        "cs" to texteCS(),
        "pl" to textePL(),
        "pt" to textePT(),
        "pt-PT" to textePTPT(),
        "ja" to texteJA(),
        "zh" to texteZH(),
        "ru" to texteRU(),
        "id" to texteID(),
        "nb" to texteNB(),
    )
}

/** Text eines Teams-Schluessels in der Sprache `lang`, null wenn es ihn hier nicht gibt. */
internal fun teamsText(key: String, lang: String): String? {
    if (!key.startsWith("team.") && !key.startsWith("sd.avgHr") && !key.startsWith("leader.total")) return null
    return TEAMS_TEXTE[lang]?.get(key)
        ?: TEAMS_BRUECKE[lang]?.let { TEAMS_TEXTE[it]?.get(key) }
        ?: TEAMS_TEXTE["en"]?.get(key)
}

