    "team.qrTeilen" to "QR-Code teilen",
    "team.regeln.beitreten.text" to "Lässt ein Team Anmeldungen zu, steht auf seiner Seite ein Knopf „Beitreten“. Je nach Einstellung ist man sofort Mitglied, oder die Leitung bzw. ein Moderator entscheidet.\nEs gibt zwei Einladungslinks: einen, mit dem man sofort Mitglied ist, und einen, mit dem man eine Anfrage stellt. Beide gibt es auch als QR-Code.\nWer noch kein Konto hat, legt eins an und ist danach direkt im Team bzw. hat angefragt.\nEin neu erzeugter Link ersetzt den alten, der alte gilt dann nicht mehr.\nMit jedem Beitritt stimmst du zu, dass die Bestenlisten des Teams öffentlich sein können, auch wenn sie es gerade nicht sind.\nBei einer Anfrage sehen Leitung und Moderatoren, an welchen Spots und in welchen Sportarten du bisher unterwegs warst (nur die Zahl der Sessions).",
