    "team.regeln.chat.text" to "Den Team-Chat lesen und schreiben nur aktive Mitglieder. Wer nur angefragt hat, sieht ihn nicht.\nEr taucht für andere nirgends auf, auch nicht unter den aktiven Chats.\nWer austritt oder entfernt wird, verliert den Zugang sofort und bekommt keine Benachrichtigungen mehr.",
    "team.regeln.chat.titel" to "Team-Chat",
    "team.regeln.events.text" to "Ein Event hat ein Zeitfenster und eigene Bestenlisten, auf Wunsch nur an bestimmten Spots.\nZusätzlich oder statt Bestenlisten kann ein Event Gesamtsummen über alle Teilnehmer zeigen, etwa die Pumps oder die Strecke des ganzen Teams. Jedes Event braucht mindestens eine Bestenliste oder eine Summe.\nEs zählen nur Sessions, die im Zeitfenster starten.\nDie Leitung kann je Event festlegen, dass von Hand hochgeladene Dateien (FIT, GPX, TCX) nicht zählen; Aufnahmen von Uhr, App und Kontoverknüpfungen zählen dann weiter.\nNach dem Ende kann man noch 4 Stunden hochladen, die Teamseite zeigt dann „Auswertung“. Danach ist das Ergebnis eingefroren, späteres Zuschneiden oder Löschen ändert nichts mehr.\nWer nach dem Ende austritt, bleibt im Ergebnis; wer danach beitritt, kommt nicht mehr hinein.\nEingefroren wird nachts und zusätzlich, sobald jemand die Teamseite aufruft.\nDie Zeiten gelten in der Zeitzone, in der das Event angelegt wurde, und werden für alle so angezeigt.\nPlatz 1 bis 3 bekommen ein Event-Abzeichen auf ihrer Foiler-Seite, aber nur bei Teams, deren Auftritt freigegeben ist.",
    "team.regeln.events.titel" to "Events",
    "team.regeln.global.text" to "Globale Events veranstaltet pumpfoil.org selbst. Es zählt automatisch jeder mit passenden Sessions im Zeitfenster, ohne Beitritt und ohne Anmeldung.\nWer nicht mitmachen will, schaltet das im Profil unter „Privatsphäre“ ab („Nicht an globalen Events teilnehmen“). Dann fehlt er in Bestenlisten, Team-Wertungen, Summen und Abzeichen, auch in schon beendeten Events.\nJe Bestenliste gibt es eine Team-Wertung: die Summe der besten Mitglieder jedes Teams, in der Regel 5, bei Geschwindigkeiten (Sprints) ihr Durchschnitt. Dabei sind freigegebene Teams mit öffentlichen Bestenlisten. Wer in mehreren Teams ist, zählt nur für eines: das auf der Eventseite gewählte, sonst sein primäres Team (★, auf der Teamseite oder unter „Meine Teams“ festgelegt). Ohne eigene Wahl bleibt beim Beitritt zu einem weiteren Team das bisherige das primäre – ein neues oder größer gewordenes Team übernimmt nie von selbst. Eigene Teams, die nicht zählen (nicht freigegeben oder Bestenlisten nicht öffentlich), stehen auf der Eventseite ausgegraut daneben. Ändern lässt sich das bis 6 Stunden vor Event-Ende.\nDie Bestenlisten sind auch ohne Anmeldung über den Event-Link sichtbar: Platz, Anzeigename, Initialen und Wert.\nSonst gelten die Regeln für Events: Zeitfenster, Auswertung, Einfrieren und Abzeichen für Platz 1 bis 3, auf der Profilseite mit „Global“ gekennzeichnet.",
    "team.regeln.global.titel" to "Globale Events",
    "team.regeln.intro" to "So funktionieren Teams auf pumpfoil.org: wer was sieht, wie gewertet wird und was beim Löschen passiert.",
    "team.regeln.konto.text" to "Die Person verschwindet aus allen Teams, Bestenlisten und auch aus eingefrorenen Event-Ergebnissen. Die Plätze darunter rücken auf.\nLeitete sie ein Team, übernimmt der dienstälteste Moderator, sonst das dienstälteste Mitglied. Ist niemand mehr da, wird das Team gelöscht.",
    "team.regeln.konto.titel" to "Wenn ein Konto gelöscht wird",
    "team.regeln.link" to "Team-Regeln",
    "team.regeln.loeschen.text" to "Löschen kann nur die Teamleitung, und nur wenn sie den Teamnamen zur Bestätigung eintippt.\nDann ist das Team für alle verschwunden: Mitgliedschaften, Bestenlisten, Logbuch, Events und der Team-Chat. Die Daten heben wir vorerst auf, damit sich ein versehentlich gelöschtes Team wiederherstellen lässt.\nDie Adresse des Teams bleibt gesperrt und wird nie an ein anderes Team vergeben.",
    "team.regeln.loeschen.titel" to "Team löschen",
    "team.regeln.logbuch.text" to "Das Logbuch hält fest, wer wann welchen Teamrekord gebrochen hat. Es wird jede Nacht nachgeführt.\nDer erste Eintrag einer Bestenliste ist der Stand in der ersten Nacht nach dem Anlegen.\nBei Bestwerten zählt jede Steigerung, auch die eigene. Bei Summen zählt nur, wenn jemand die Spitze übernimmt.\nSinkt ein Rekord, weil eine Session gelöscht wurde oder jemand ausgetreten ist, wird das still nachgezogen, ohne Eintrag.",
    "team.regeln.logbuch.titel" to "Logbuch",
    "team.regeln.oeffentlich.text" to "Intern darf ein Team alles. Nach außen erscheint es erst, wenn wir Name, Adresse, Beschreibung, Wappen und Farbe einmal angesehen und freigegeben haben.\nDas Teambild läuft durch dieselbe Freigabe wie das Wappen. Welchen Ausschnitt man sieht, wählt die Leitung ohne neue Freigabe; entfernt sie das Bild, verschwindet es sofort auch nach außen.\nÄndert ein freigegebenes Team seinen Auftritt, gilt das im Team sofort, nach außen erst nach erneuter Freigabe.\nFreigegebene Teams stehen auf der Seite „Alle Teams“. Ihre Events stehen auf der Teamseite; in der Community stehen nur die globalen Events von pumpfoil.org.\nSchaltet die Leitung die Bestenlisten öffentlich, sieht sie jeder, auch ohne Anmeldung, aber nur Platz, Anzeigename, Initialen und Wert. Sessions, Spots, Daten und Profilbilder sehen nur angemeldete Nutzer.\nSuchmaschinen nehmen Teamseiten nicht auf.\nWer die Mitgliederliste sieht, legt die Leitung fest: nur Mitglieder oder alle Angemeldeten.",
    "team.regeln.oeffentlich.titel" to "Was öffentlich ist",
    "team.regeln.rollen.text" to "Die Teamleitung darf alles: Einstellungen, Bestenlisten, Events, Moderatoren benennen, die Leitung übergeben und das Team löschen.\nModeratoren nehmen Anfragen an oder lehnen sie ab, entfernen Mitglieder und legen Events an. Sonst ändern sie nichts.\nMitglieder sehen alles im Team und können jederzeit austreten.\nDie Leitung kann erst austreten, wenn sie die Leitung übergeben hat.",
    "team.regeln.rollen.titel" to "Rollen",
    "team.regeln.statistik.text" to "Über den Bestenlisten stehen die Summen aller Mitglieder im gewählten Zeitraum: Pumps, On-Foil-Strecke und -Zeit, Sessions, Läufe und wie viele Mitglieder aktiv waren.\nTeam gegen Team: In der Community vergleichen die Team-Bestenlisten alle freigegebenen Teams mit öffentlichen Bestenlisten, je Kennzahl mit der Summe der besten 3, 5 oder 10 Fahrer. Dort gilt für alle Teams dasselbe Maß, nicht die Filter der eigenen Bestenlisten.\nWer in zwei Teams ist, zählt für beide.",
    "team.regeln.statistik.titel" to "Teamsummen",
    "team.regeln.titel" to "Team-Regeln",
    "team.regeln.was.text" to "Eine feste Gruppe mit eigenen Bestenlisten, Events und einem Team-Chat.\nJeder kann Teams gründen, auch mehrere, und in mehreren Teams sein.\nEin neues Team funktioniert sofort, über Einladungslinks.",
    "team.regeln.was.titel" to "Was ist ein Team?",
