    "team.loeschenKnopf" to "Für immer lösche",
    "team.loeschenText" to "S Team isch sofort für alli wäg, mit Bestelischte, Events und Team-Chat. Mir bhalted d Date vorläufig, demit mer es us Versehe glöschts Team wieder härestelle chönd. Zur Bestätigung de Teamname „{name}“ iitippe.",
