    "team.name" to "Teamname",
    "team.nichtGefunden" to "Das Team gits nöd, oder es isch nöd öffentlich.",
    "team.nurFuerMitglieder" to "D Bestelischte vo dem Team gsehnd nume Mitglieder.",
