    "team.oeffentlichBadge" to "Bestelischte öffentlich",
    "team.oeffentlichErstNachFreigabe" to "Gilt erscht, wenn de Uftritt freigä isch.",
    "team.oeffentlichText" to "Denn gseht jede d Bestelischte, au ohni Aamäldig: Platz, Aazeigname und Wert. Sessions, Spots und Profilbilder gsehnd nume Aagmeldeti.",
