    "team.podest.fahrer" to "Fahrer",
    "team.podest.stumm" to "Stumm",
    "team.podest.ton" to "Siegerton abspiele",
    "team.primaer" to "Primärs Team",
    "team.primaerHinweis" to "I globale Events zellsch du nur für eis Team: dis primäre, usser du wählsch uf de Eventsiite es anders.",
    "team.primaerSetzen" to "Als primärs Team feschtlegge",
    "team.profilHinweis" to "Teams gründe, biitrete und eigeni Bestelischte füehre.",
    "team.profilKnopf" to "Team",
    "team.qr" to "QR-Code",
    "team.qrLaden" to "QR-Code spichere",
    "team.qrTeilen" to "QR-Code teile",
    "team.regeln.beitreten.text" to "Lat es Team Aamäldige zue, staht uf sinere Siite en Chnopf „Biitrete“. Je nach Iistellig isch mer sofort Mitglied, oder d Leitig bzw. en Moderator entscheidet.\nEs git zwei Iiladigslinks: eine, mit dem mer sofort Mitglied isch, und eine, mit dem mer e Aafrog stellt. Beidi gits au als QR-Code.\nWer no kei Konto het, macht eis und isch drnoch grad im Team bzw. het aagfrogt.\nEn neue Link ersetzt de alt, de alt gilt denn nüm.\nMit jedem Biitritt bisch iiverstande, dass d Bestelischte vom Team öffentlich chönd sii, au wenn sie's grad nöd sind.\nBi ere Aafrog gsehnd d Leitig und d Moderatore, a wele Spots und i wele Sportarte du bis jetzt unterwägs gsi bisch (nur d Zahl vo de Sessions).",
    "team.regeln.beitreten.titel" to "Biitrete",
    "team.regeln.bestenlisten.text" to "Pro Person zählt nume ein Iitrag: de bescht Wert us einere Session, oder bi Summe alles im gwählte Ziitruum zäme.\nEs zähled alli Sessions vo de Mitglieder, au die vo vor em Biitritt. Wer uustritt, verschwindet sofort us de Lischte.\nBi Events gilt das nur bis zum Änd, lueg under „Events“.\nEs gälted die gliiche Filter wie bi de Community-Rekord: glöschti, gmeldeti, nöd zuegordneti und laufendi Ufnahme zähled nöd.\nJedi Bestelischte cha uf e Sportart, es Foil-Band, Ufnahme mit Bewegigsdate, s Handy am Brätt oder d Teamspots iigschränkt werde.\nIsch „Ort verberge“ aa, zählt d Session nie für en bestimmte Spot.\nBi Gliichstand isch vorne, wer de Wert zerscht gfahre isch.",
    "team.regeln.bestenlisten.titel" to "Bestelischte",
    "team.regeln.chat.text" to "De Team-Chat läsed und schriibed nume aktivi Mitglieder. Wer nume aagfrogt het, gseht ne nöd.\nEr taucht für anderi niene uf, au nöd under de aktive Chats.\nWer uustritt oder usegno wird, verlüürt de Zuegang sofort und überchunnt kei Benachrichtigunge meh.",
    "team.regeln.chat.titel" to "Team-Chat",
    "team.regeln.events.text" to "Es Event het es Ziitfänschter und eigeni Bestelischte, wenn mer will nume a bestimmte Spots.\nZuesätzlich oder statt Bestelischte cha en Event Gsamtsumme über alli Teilnähmer zeige, öppe d Pumps oder d Strecki vom ganze Team. Jede Event bruucht mindestens e Bestelischte oder e Summe.\nEs zähled nume Sessions, wo im Ziitfänschter aafanged.\nD Leitig cha pro Event feschtlege, dass vo Hand uegladeni Dateie (FIT, GPX, TCX) nöd zelled; Ufnahme vo Uhr, App und Kontoverchnüpfige zelled denn wiiter.\nNach em Änd cha mer no 4 Stund uelade, d Teamsiite zeigt denn „Uswärtig“. Drnoch isch s Resultat iigfrore, spöters Zueschniide oder Lösche ändered nüt meh.\nWer nach em Änd ustritt, blibt im Ergebnis; wer dänn biitritt, chunnt nüme drii.\nIigfrore wird znacht und zuesätzlich, sobald öpper d Teamsiite uftuet.\nD Ziite gälted i de Ziitzone, i dere s Event aagleit worde isch, und werded für alli so aazeigt.\nPlatz 1 bis 3 überchömed es Event-Abzeiche uf ihrere Foiler-Siite, aber nume bi Teams, wo de Uftritt freigä isch.",
    "team.regeln.events.titel" to "Events",
    "team.regeln.global.text" to "Globali Events veranstaltet pumpfoil.org sälber. Es zellt automatisch jede mit passende Sessions im Ziitfänschter, ohni Biitritt und ohni Aamäldig.\nWär nöd mitmache wott, schaltet das im Profil under „Privatsphäre“ ab („Nöd a globale Events teilneh“). Dänn fehlt er i Bestelischte, Team-Wärtige, Summe und Abzeiche, au i scho beändete Events.\nPro Beschtelischte gits e Team-Wertig: d Summe vo de beschte Mitglieder vo jedem Team, i de Regle 5, bi Gschwindigkeite (Sprints) ihre Durchschnitt. Debii sind freigeh Teams mit öffentliche Beschtelischte. Wer i mehrere Teams isch, zellt nur für eis: das, wo uf de Eventsiite gwählt isch, susch sis primäre Team (★, uf de Teamsiite oder under „Mini Teams“ feschtgleit). Ohni eigeni Wahl blibt bim Biitritt zu emne wiitere Team s bisherige s primäre – es neus oder gröschter wordnigs Team übernimmt nie vo sälber. Eigeni Teams, wo nöd zelle (nöd freigeh oder Beschtelischte nöd öffentlich), stönd uf de Eventsiite grau dernäbe. Ändere chasch das bis 6 Stund vor em Event-Änd.\nD Bestelischte sind au ohni Aamäldig über de Event-Link sichtbar: Platz, Aazeigname, Initiale und Wärt.\nSuscht gälted d Regle für Events: Ziitfänschter, Uswärtig, Iifriere und Abzeiche für Platz 1 bis 3, uf de Profilsiite mit „Global“ gchennzeichnet.",
    "team.regeln.global.titel" to "Globali Events",
    "team.regeln.intro" to "So funktioniered Teams uf pumpfoil.org: wer was gseht, wie gwertet wird und was bim Lösche passiert.",
    "team.regeln.konto.text" to "D Person verschwindet us allne Teams, Bestelischte und au us iigfrorene Event-Resultat. D Plätz drunder rucked uf.\nHet sie es Team gleitet, übernimmt de dienschtältischt Moderator, susch s dienschtältischt Mitglied. Isch niemer meh da, wird s Team glöscht.",
    "team.regeln.konto.titel" to "Wenn es Konto glöscht wird",
    "team.regeln.link" to "Team-Regle",
    "team.regeln.loeschen.text" to "Lösche cha nume d Teamleitig, und nume wenn sie de Teamname zum Bestätige iitippt.\nDenn isch s Team für alli wäg: Mitgliedschafte, Bestelischte, Logbuech, Events und de Team-Chat. D Date bhalted mir vorläufig, demit mer es us Versehe glöschts Team wieder härestelle chönd.\nD Adrässe vom Team blibt gsperrt und wird nie amne andere Team vergä.",
    "team.regeln.loeschen.titel" to "Team lösche",
    "team.regeln.logbuch.text" to "S Logbuech hebt fescht, wer wänn welle Teamrekord broche het. Es wird jedi Nacht nachgfüehrt.\nDe erscht Iitrag vo einere Bestelischte isch de Stand i de erschte Nacht nach em Aalege.\nBi Beschtwärt zählt jedi Steigerig, au di eige. Bi Summe zählt's nume, wenn öpper d Spitze übernimmt.\nSinkt en Rekord, will e Session glöscht worde isch oder öpper uustrete isch, wird das still nachzoge, ohni Iitrag.",
    "team.regeln.logbuch.titel" to "Logbuech",
    "team.regeln.oeffentlich.text" to "Intern dörf es Team alles. Gäge usse taucht's erscht uf, wenn mir Name, Adrässe, Beschriibig, Wappe und Farb eimal aagluegt und freigä händ.\nS Teambild gaht dur di glich Freigab wie s Wappe. Weli Usschnitt mer gseht, wählt d Leitig ohni neui Freigab; nimmt si s Bild use, isch es sofort au usse wäg.\nÄnderet es freigäs Team sin Uftritt, gilt das im Team sofort, gäge usse erscht nach erneuter Freigab.\nFreigäni Teams stönd uf de Siite „Alli Teams“. Ihri Events stönd uf de Teamsiite; i de Community stönd nur di globale Events vo pumpfoil.org.\nSchaltet d Leitig d Bestelischte öffentlich, gseht sie jede, au ohni Aamäldig, aber nume Platz, Aazeigname, Initiale und Wert. Sessions, Spots, Datum und Profilbilder gsehnd nume Aagmeldeti.\nSuechmaschine nämed Teamsiite nöd uf.\nWer d Mitgliederlischte gseht, bestimmt d Leitig: nume Mitglieder oder alli Aagmeldete.",
    "team.regeln.oeffentlich.titel" to "Was öffentlich isch",
    "team.regeln.rollen.text" to "D Teamleitig dörf alles: Iistellige, Bestelischte, Events, Moderatore bestimme, d Leitig übergä und s Team lösche.\nModeratore nämed Aafroge aa oder lehned sie ab, nämed Mitglieder use und leged Events aa. Susch ändered sie nüt.\nMitglieder gsehnd alles im Team und chönd jederziit uustrete.\nD Leitig cha erscht uustrete, wenn sie d Leitig übergä het.",
    "team.regeln.rollen.titel" to "Rolle",
    "team.regeln.statistik.text" to "Über de Bestelischte stönd d Summe vo allne Mitglieder im gwählte Ziitruum: Pumps, On-Foil-Strecki und -Ziit, Sessions, Läuf und wie vill Mitglieder aktiv gsi sind.\nTeam gäge Team: I de Community vergliichet d Team-Bestelischte alli freigäne Teams mit öffentliche Bestelischte, pro Kennzahl mit de Summe vo de beschte 3, 5 oder 10 Fahrer. Det gilt für alli Teams s gliiche Mass, nöd d Filter vo de eigete Bestelischte.\nWär i zwei Teams isch, zellt für beidi.",
    "team.regeln.statistik.titel" to "Teamsumme",
    "team.regeln.titel" to "Team-Regle",
    "team.regeln.was.text" to "E feschti Gruppe mit eigene Bestelischte, Events und emne Team-Chat.\nJede cha Teams gründe, au mehreri, und i mehrere Teams sii.\nEs neus Team lauft sofort, über Iiladigslinks.",
    "team.regeln.was.titel" to "Was isch es Team?",
    "team.rolle.leiter" to "Leitig",
    "team.rolle.mitglied" to "Mitglied",
    "team.rolle.moderator" to "Moderator",
    "team.rolleUebergeben" to "Leitig übergä",
    "team.sichtbar.angemeldete" to "Alli Aagmeldete",
    "team.sichtbar.mitglieder" to "Nume Mitglieder",
