    "team.linksHinweis" to "Zwa Links zum Verteilen. Wer no ka Konto hat, legt ans an und is dann gleich dabei.",
    "team.loeschen" to "Team löschen",
    "team.loeschenKnopf" to "Endgültig löschen",
    "team.loeschenText" to "Das Team ist sofort für alle weg, mit Bestenlisten, Events und Team-Chat. Wir heben die Daten vorerst auf, damit sich ein versehentlich gelöschtes Team wiederherstellen lässt. Zur Bestätigung den Teamnamen „{name}“ eintippen.",
    "team.logbuch" to "Logbuch",
    "team.logbuch.gebrochen" to "{name} bricht „{was}“ mit {wert} (vorher {vorher}, {vorherWert})",
    "team.logbuch.start" to "{name} hält „{was}“ mit {wert}",
    "team.logbuchHinweis" to "Wer wann welchen Teamrekord brochen hat. Wird jede Nacht nachtragen.",
    "team.logbuchLeer" to "No ka Einträge. Der erste Stand kommt in der Nacht nachm Anlegen der Bestenlisten.",
    "team.logoHochladen" to "Wappen raufladen",
    "team.meine" to "Meine Teams",
    "team.mitglieder" to "Mitglieder",
    "team.mitgliederAnzahl" to "{n} Mitglieder",
    "team.mitgliederSichtbar" to "Wer sieht die Mitgliederliste?",
    "team.name" to "Teamnam",
    "team.nichtGefunden" to "Des Team gibt's ned, oder es is ned öffentlich.",
    "team.nurFuerMitglieder" to "Die Bestenlisten von dem Team sehn nur Mitglieder.",
    "team.oeffentlich" to "Bestenlisten öffentlich",
    "team.oeffentlichBadge" to "Bestenlisten öffentlich",
    "team.oeffentlichErstNachFreigabe" to "Gilt erst, wenn der Auftritt freigeben is.",
    "team.oeffentlichText" to "Dann sieht jeder die Bestenlisten, a ohne Anmeldung: Platz, Anzeigenam und Wert. Sessions, Spots und Profilbilder sehn nur Ang'meldete.",
    "team.platz1" to "1. Platz",
    "team.platz2" to "2. Platz",
    "team.platz3" to "3. Platz",
    "team.podest.fahrer" to "Fahrer",
    "team.podest.stumm" to "Stumm",
    "team.podest.ton" to "Siegerton abspielen",
    "team.primaer" to "Primäres Team",
    "team.primaerHinweis" to "In globalen Events zählst du nur für ein Team: dein primäres, außer du wählst auf der Eventseite ein anderes.",
    "team.primaerSetzen" to "Als primäres Team festlegen",
    "team.profilHinweis" to "Teams gründen, beitreten und eigene Bestenlisten führen.",
    "team.profilKnopf" to "Team",
    "team.qr" to "QR-Code",
    "team.qrLaden" to "QR-Code speichern",
    "team.qrTeilen" to "QR-Code teilen",
    "team.regeln.beitreten.text" to "Lasst a Team Anmeldungen zu, steht auf seiner Seite a Knopf „Beitreten“. Je nach Einstellung is ma sofort Mitglied, oder die Leitung bzw. a Moderator entscheidet.\nEs gibt zwa Einladungslinks: an, mit dem ma sofort Mitglied is, und an, mit dem ma a Anfrage stellt. Beide gibt's a als QR-Code.\nWer no ka Konto hat, legt ans an und is dann gleich im Team bzw. hat ang'fragt.\nA neu g'machter Link ersetzt den alten, der alte gilt dann nimma.\nMit jedem Beitritt bist einverstanden, dass die Bestenlisten vom Team öffentlich sein können, a wenn s' es grad ned san.\nBei einer Anfrage sehen Leitung und Moderatoren, an welchen Spots und in welchen Sportarten du bisher unterwegs warst (nur die Zahl der Sessions).",
    "team.regeln.beitreten.titel" to "Beitreten",
    "team.regeln.bestenlisten.text" to "Pro Person zählt nur a Eintrag: der beste Wert aus aner Session, oder bei Summen alles im g'wählten Zeitraum z'samm.\nEs zählen alle Sessions der Mitglieder, a die von vorm Beitritt. Wer austritt, verschwindet sofort aus die Listen.\nBei Events gilt das nur bis zum Ende, siehe „Events“.\nEs gelten die gleichen Filter wie bei die Community-Rekorde: g'löschte, g'meldete, ned zug'ordnete und laufende Aufnahmen zählen ned.\nJede Bestenliste kann auf a Sportart, a Foil-Band, Aufnahmen mit Bewegungsdaten, des Handy am Brett oder die Teamspots eing'schränkt werden.\nIs „Ort verbergen“ an, zählt die Session nie für an bestimmten Spot.\nBei Gleichstand is vorn, wer den Wert zerst g'fahren is.",
    "team.regeln.bestenlisten.titel" to "Bestenlisten",
    "team.regeln.chat.text" to "Den Team-Chat lesen und schreiben nur aktive Mitglieder. Wer nur ang'fragt hat, sieht ihn ned.\nEr taucht für andere nirgends auf, a ned unter die aktiven Chats.\nWer austritt oder rausg'nommen wird, verliert den Zugang sofort und kriegt ka Benachrichtigungen mehr.",
    "team.regeln.chat.titel" to "Team-Chat",
    "team.regeln.events.text" to "A Event hat a Zeitfenster und eigene Bestenlisten, wenn ma will nur an bestimmten Spots.\nZusätzlich oder statt Bestenlisten kann ein Event Gesamtsummen über alle Teilnehmer zeigen, etwa die Pumps oder die Strecke des ganzen Teams. Jedes Event braucht mindestens eine Bestenliste oder eine Summe.\nEs zählen nur Sessions, die im Zeitfenster anfangen.\nDie Leitung kann je Event festlegen, dass von Hand hochgeladene Dateien (FIT, GPX, TCX) nicht zählen; Aufnahmen von Uhr, App und Kontoverknüpfungen zählen dann weiter.\nNachm Ende kann ma no 4 Stunden raufladen, die Teamseite zeigt dann „Auswertung“. Danach is des Ergebnis eing'froren, späteres Zuschneiden oder Löschen ändert nix mehr.\nWer nach dem Ende austritt, bleibt im Ergebnis; wer danach beitritt, kommt nicht mehr hinein.\nEing'froren wird in der Nacht und zusätzlich, sobald wer die Teamseite aufmacht.\nDie Zeiten gelten in der Zeitzone, in der des Event ang'legt worden is, und werden für alle so anzeigt.\nPlatz 1 bis 3 kriegen a Event-Abzeichen auf ihrer Foiler-Seite, aber nur bei Teams, deren Auftritt freigeben is.",
    "team.regeln.events.titel" to "Events",
    "team.regeln.global.text" to "Globale Events veranstaltet pumpfoil.org selbst. Es zählt automatisch jeder mit passenden Sessions im Zeitfenster, ohne Beitritt und ohne Anmeldung.\nWer ned mitmachen will, schaltet das im Profil unter „Privatsphäre“ ab („Nicht an globalen Events teilnehmen“). Dann fehlt er in Bestenlisten, Team-Wertungen, Summen und Abzeichen, auch in schon beendeten Events.\nJe Bestenliste gibt es eine Team-Wertung: die Summe der besten Mitglieder jedes Teams, in der Regel 5, bei Geschwindigkeiten (Sprints) ihr Durchschnitt. Dabei sind freigegebene Teams mit öffentlichen Bestenlisten. Wer in mehreren Teams ist, zählt nur für eines: das auf der Eventseite gewählte, sonst sein primäres Team (★, auf der Teamseite oder unter „Meine Teams“ festgelegt). Ohne eigene Wahl bleibt beim Beitritt zu einem weiteren Team das bisherige das primäre – ein neues oder größer gewordenes Team übernimmt nie von selbst. Eigene Teams, die nicht zählen (nicht freigegeben oder Bestenlisten nicht öffentlich), stehen auf der Eventseite ausgegraut daneben. Ändern lässt sich das bis 6 Stunden vor Event-Ende.\nDie Bestenlisten sind auch ohne Anmeldung über den Event-Link sichtbar: Platz, Anzeigename, Initialen und Wert.\nSonst gelten die Regeln für Events: Zeitfenster, Auswertung, Einfrieren und Abzeichen für Platz 1 bis 3, auf der Profilseite mit „Global“ gekennzeichnet.",
    "team.regeln.global.titel" to "Globale Events",
    "team.regeln.intro" to "So funktionieren Teams auf pumpfoil.org: wer was sieht, wie g'wertet wird und was beim Löschen passiert.",
    "team.regeln.konto.text" to "Die Person verschwindet aus allen Teams, Bestenlisten und a aus eing'frorenen Event-Ergebnissen. Die Plätze drunter rücken auf.\nHat s' a Team g'leitet, übernimmt der dienstälteste Moderator, sonst des dienstälteste Mitglied. Is niemand mehr da, wird des Team g'löscht.",
    "team.regeln.konto.titel" to "Wenn a Konto g'löscht wird",
    "team.regeln.link" to "Team-Regeln",
    "team.regeln.loeschen.text" to "Löschen kann nur die Teamleitung, und nur wenn s' den Teamnam zum Bestätigen eintippt.\nDann ist das Team für alle weg: Mitgliedschaften, Bestenlisten, Logbuch, Events und der Team-Chat. Die Daten heben wir vorerst auf, damit sich ein versehentlich gelöschtes Team wiederherstellen lässt.\nDie Adresse vom Team bleibt g'sperrt und wird nie an a anderes Team vergeben.",
    "team.regeln.loeschen.titel" to "Team löschen",
    "team.regeln.logbuch.text" to "Des Logbuch hält fest, wer wann welchen Teamrekord brochen hat. Es wird jede Nacht nachtragen.\nDer erste Eintrag von aner Bestenliste is der Stand in der ersten Nacht nachm Anlegen.\nBei Bestwerten zählt jede Steigerung, a die eigene. Bei Summen zählt's nur, wenn wer die Spitze übernimmt.\nSinkt a Rekord, weil a Session g'löscht worden oder wer ausgetreten is, wird des still nachzogen, ohne Eintrag.",
    "team.regeln.logbuch.titel" to "Logbuch",
    "team.regeln.oeffentlich.text" to "Intern darf a Team alles. Nach außen taucht's erst auf, wenn ma Nam, Adresse, Beschreibung, Wappen und Farb amal ang'schaut und freigeben ham.\nDas Teambild geht durch dieselbe Freigabe wie das Wappen. Welchen Ausschnitt man sieht, sucht sich die Leitung ohne neue Freigabe aus; nimmt sie das Bild raus, ist es sofort auch nach außen weg.\nÄndert a freigebenes Team sein' Auftritt, gilt des im Team sofort, nach außen erst nach neuer Freigabe.\nFreigegebene Teams stehen auf der Seite „Alle Teams“. Ihre Events stehen auf der Teamseite; in der Community stehen nur die globalen Events von pumpfoil.org.\nSchaltet die Leitung die Bestenlisten öffentlich, sieht s' jeder, a ohne Anmeldung, aber nur Platz, Anzeigenam, Initialen und Wert. Sessions, Spots, Datum und Profilbilder sehn nur Ang'meldete.\nSuchmaschinen nehmen Teamseiten ned auf.\nWer die Mitgliederliste sieht, bestimmt die Leitung: nur Mitglieder oder alle Ang'meldeten.",
    "team.regeln.oeffentlich.titel" to "Was öffentlich is",
    "team.regeln.rollen.text" to "Die Teamleitung darf alles: Einstellungen, Bestenlisten, Events, Moderatoren bestimmen, die Leitung übergeben und des Team löschen.\nModeratoren nehmen Anfragen an oder lehnen s' ab, nehmen Mitglieder raus und legen Events an. Sonst ändern s' nix.\nMitglieder sehn alles im Team und können jederzeit austreten.\nDie Leitung kann erst austreten, wenn s' die Leitung übergeben hat.",
    "team.regeln.rollen.titel" to "Rollen",
    "team.regeln.statistik.text" to "Über die Bestenlisten stehn die Summen von allen Mitgliedern im g'wählten Zeitraum: Pumps, On-Foil-Strecke und -Zeit, Sessions, Läufe und wie viele Mitglieder aktiv waren.\nTeam gegen Team: In der Community vergleichen die Team-Bestenlisten alle freigegebenen Teams mit öffentlichen Bestenlisten, je Kennzahl mit der Summe der besten 3, 5 oder 10 Fahrer. Dort gilt für alle Teams dasselbe Maß, ned die Filter der eigenen Bestenlisten.\nWer in zwei Teams is, zählt für beide.",
    "team.regeln.statistik.titel" to "Teamsummen",
    "team.regeln.titel" to "Team-Regeln",
    "team.regeln.was.text" to "A fixe Partie mit eigenen Bestenlisten, Events und an Team-Chat.\nJeder kann Teams gründen, a mehrere, und in mehreren Teams sein.\nA neues Team rennt sofort, über Einladungslinks.",
    "team.regeln.was.titel" to "Was is a Team?",
    "team.rolle.leiter" to "Leitung",
    "team.rolle.mitglied" to "Mitglied",
    "team.rolle.moderator" to "Moderator",
    "team.rolleUebergeben" to "Leitung übergeben",
    "team.sichtbar.angemeldete" to "Alle Ang'meldeten",
    "team.sichtbar.mitglieder" to "Nur Mitglieder",
    "team.sichtbarkeit" to "Sichtbarkeit",
    "team.spotHinzu" to "Dazugeben",
    "team.spotWaehlen" to "Spot auswählen …",
    "team.spots" to "Teamspots",
    "team.spotsHinweis" to "Bestenlisten mit „nur Teamspots“ zählen nur Sessions an die Spots.",
    "team.stat.aktiv" to "aktiv",
    "team.stat.laeufe" to "Läufe",
    "team.stat.pumps" to "Pumps",
    "team.stat.sessions" to "Sessions",
    "team.stat.strecke" to "On-Foil-Strecke",
