    "team.nichtGefunden" to "This team doesn't exist or isn't public.",
    "team.nurFuerMitglieder" to "Only members can see this team's leaderboards.",
    "team.oeffentlich" to "Public leaderboards",
    "team.oeffentlichBadge" to "Public leaderboards",
    "team.oeffentlichErstNachFreigabe" to "Takes effect once the appearance is approved.",
    "team.oeffentlichText" to "Everyone can then see the leaderboards, even without signing in: rank, display name and value. Sessions, spots and profile pictures stay visible to signed-in users only.",
    "team.platz1" to "1st place",
    "team.platz2" to "2nd place",
    "team.platz3" to "3rd place",
    "team.podest.fahrer" to "Riders",
    "team.podest.stumm" to "Mute",
    "team.podest.ton" to "Play winner sound",
    "team.primaer" to "Primary team",
    "team.primaerHinweis" to "In global events you count for one team only: your primary team, unless you pick another one on the event page.",
    "team.primaerSetzen" to "Make primary team",
    "team.profilHinweis" to "Start or join teams with their own leaderboards.",
    "team.profilKnopf" to "Team",
    "team.qr" to "QR code",
    "team.qrLaden" to "Save QR code",
    "team.qrTeilen" to "Share QR code",
    "team.regeln.beitreten.text" to "If a team allows sign-ups, its page shows a “Join” button. Depending on the setting you're in right away, or the lead or a moderator decides.\nThere are two invite links: one that makes you a member right away and one that sends a request. Both are also available as QR codes.\nAnyone without an account creates one and is then straight in the team, or has sent the request.\nA newly created link replaces the old one, which then stops working.\nEvery time you join, you agree that the team's leaderboards may be public, even if they aren't right now.\nWith a request, the team lead and moderators see which spots and sports you have been out on so far (only the number of sessions).",
    "team.regeln.beitreten.titel" to "Joining",
    "team.regeln.bestenlisten.text" to "Each person counts once: their best value from a single session, or for totals everything in the chosen period added up.\nAll of a member's sessions count, including those from before they joined. Anyone who leaves disappears from the lists right away.\nFor events this only applies until the end, see “Events”.\nThe same filters apply as for the community records: deleted, reported, unassigned and ongoing recordings don't count.\nEach leaderboard can be limited to one sport, a foil band, recordings with motion data, the phone on the board, or the team spots.\nIf “Hide location” is on, the session never counts for a particular spot.\nOn a tie, whoever rode the value first comes first.",
    "team.regeln.bestenlisten.titel" to "Leaderboards",
    "team.regeln.chat.text" to "Only active members can read and write in the team chat. Anyone who has only sent a request can't see it.\nIt never shows up for others, not even among the active chats.\nAnyone who leaves or is removed loses access right away and gets no more notifications.",
    "team.regeln.chat.titel" to "Team chat",
    "team.regeln.events.text" to "An event has a time window and its own leaderboards, optionally only at certain spots.\nIn addition to or instead of leaderboards, an event can show totals across all participants, such as the whole team's pumps or distance. Every event needs at least one leaderboard or one total.\nOnly sessions that start within the window count.\nFor each event the team lead can decide that manually uploaded files (FIT, GPX, TCX) don't count; recordings from watches, the app and linked accounts still count.\nAfter the end you can still upload for 4 hours; the team page then shows “results pending”. After that the result is frozen, and later trimming or deleting no longer changes anything.\nAnyone who leaves after the end stays in the result; anyone who joins afterwards is not added.\nResults are frozen at night and also as soon as someone opens the team page.\nTimes are in the time zone the event was created in and are shown that way to everyone.\nPlaces 1 to 3 get an event badge on their foiler page, but only for teams whose appearance is approved.",
    "team.regeln.events.titel" to "Events",
    "team.regeln.global.text" to "Global events are organised by pumpfoil.org itself. Everyone with matching sessions in the time window counts automatically, without joining and without signing up.\nAnyone who doesn't want to take part can turn it off in their profile under “Privacy” (“Don't take part in global events”). They then disappear from leaderboards, team rankings, totals and badges, including events that have already ended.\nEach leaderboard has a team ranking: the sum of each team's best members, usually 5, and for speeds (sprints) their average. Approved teams with public leaderboards take part. Anyone in several teams counts for one only: the one picked on the event page, otherwise their primary team (★, set on the team page or under “My teams”). Without a choice of your own, joining another team keeps your current team as primary – a new or grown team never takes over by itself. Your teams that don’t count (not approved or leaderboards not public) are shown greyed out on the event page. This can be changed until 6 hours before the event ends.\nThe leaderboards are also visible without logging in via the event link: rank, display name, initials and value.\nOtherwise the rules for events apply: time window, evaluation, freezing, and badges for places 1 to 3, marked “Global” on the profile page.",
    "team.regeln.global.titel" to "Global events",
    "team.regeln.intro" to "How teams work on pumpfoil.org: who sees what, how things are scored, and what happens when something is deleted.",
    "team.regeln.konto.text" to "The person disappears from all teams and leaderboards, and from frozen event results too. Those below move up.\nIf they led a team, the longest-serving moderator takes over, otherwise the longest-serving member. If nobody is left, the team is deleted.",
    "team.regeln.konto.titel" to "When an account is deleted",
    "team.regeln.link" to "Team rules",
    "team.regeln.loeschen.text" to "Only the team lead can delete a team, and only by typing the team name to confirm.\nThe team is then gone for everyone: memberships, leaderboards, logbook, events and the team chat. We keep the data for now so a team deleted by mistake can be restored.\nThe team's address stays blocked and is never given to another team.",
    "team.regeln.loeschen.titel" to "Deleting a team",
    "team.regeln.logbuch.text" to "The logbook records who broke which team record, and when. It's updated every night.\nThe first entry of a leaderboard is the standing on the first night after it was set up.\nFor best values every improvement counts, including your own. For totals it only counts when someone takes the lead.\nIf a record drops because a session was deleted or someone left, it's adjusted quietly, without an entry.",
    "team.regeln.logbuch.titel" to "Logbook",
    "team.regeln.oeffentlich.text" to "Inside, a team can do anything. It only appears to others once we've looked at and approved its name, address, description, crest and colour.\nThe team banner goes through the same approval as the crest. The team lead chooses which part is visible without a new approval; if they remove the banner, it disappears from the public page right away too.\nIf an approved team changes its appearance, that applies inside the team right away, and to the public after a new approval.\nApproved teams are listed on the “All teams” page. Their events are on the team page; the community only shows the global events by pumpfoil.org.\nIf the lead makes the leaderboards public, everyone can see them, even without signing in, but only rank, display name, initials and value. Sessions, spots, dates and profile pictures are visible to signed-in users only.\nSearch engines don't index team pages.\nThe lead decides who sees the member list: members only, or all signed-in users.",
    "team.regeln.oeffentlich.titel" to "What is public",
    "team.regeln.rollen.text" to "The team lead can do everything: settings, leaderboards, events, naming moderators, handing over the lead and deleting the team.\nModerators accept or decline requests, remove members and create events. They can't change anything else.\nMembers see everything in the team and can leave at any time.\nThe lead can only leave after handing over the lead.",
    "team.regeln.rollen.titel" to "Roles",
    "team.regeln.statistik.text" to "Above the leaderboards are the totals of all members in the chosen period: pumps, on-foil distance and time, sessions, runs and how many members were active.\nTeam against team: in the community, the team leaderboards compare all approved teams with public leaderboards, per metric by the sum of the best 3, 5 or 10 riders. The same measure applies to all teams there, not the filters of their own leaderboards.\nAnyone in two teams counts for both.",
    "team.regeln.statistik.titel" to "Team totals",
