    "team.regeln.beitreten.text" to "Si une équipe accepte les inscriptions, sa page affiche un bouton « Rejoindre ». Selon le réglage, tu es membre tout de suite, ou le responsable ou un modérateur décide.\nIl existe deux liens d'invitation : l'un te rend membre tout de suite, l'autre envoie une demande. Les deux existent aussi en QR code.\nSi tu n'as pas encore de compte, tu en crées un et tu es ensuite directement dans l'équipe, ou ta demande est envoyée.\nUn nouveau lien remplace l'ancien, qui ne fonctionne alors plus.\nÀ chaque adhésion, tu acceptes que les classements de l'équipe puissent être publics, même s'ils ne le sont pas en ce moment.\nLors d'une demande, les responsables et les modérateurs voient sur quels spots et dans quels sports tu as été actif jusqu'ici (seulement le nombre de sessions).",
    "team.regeln.beitreten.titel" to "Rejoindre",
    "team.regeln.bestenlisten.text" to "Chaque personne compte une seule fois : sa meilleure valeur sur une session, ou pour les totaux, tout ce qui a été fait sur la période choisie.\nToutes les sessions des membres comptent, y compris celles d'avant leur adhésion. Qui quitte l'équipe disparaît aussitôt des classements.\nPour les événements, cela ne vaut que jusqu'à la fin, voir « Événements ».\nLes mêmes filtres que pour les records de la communauté s'appliquent : les enregistrements supprimés, signalés, non attribués et en cours ne comptent pas.\nChaque classement peut être limité à un sport, une plage de foils, les enregistrements avec données de mouvement, le téléphone sur la planche ou les spots de l'équipe.\nSi « Masquer le lieu » est activé, la session ne compte jamais pour un spot précis.\nEn cas d'égalité, celui qui a réalisé la valeur en premier passe devant.",
    "team.regeln.bestenlisten.titel" to "Classements",
    "team.regeln.chat.text" to "Seuls les membres actifs peuvent lire et écrire dans le chat d'équipe. Qui a seulement envoyé une demande ne le voit pas.\nIl n'apparaît nulle part pour les autres, pas même parmi les chats actifs.\nQui quitte l'équipe ou en est retiré perd l'accès aussitôt et ne reçoit plus de notifications.",
    "team.regeln.chat.titel" to "Chat d'équipe",
    "team.regeln.events.text" to "Un événement a une fenêtre de temps et ses propres classements, si on le souhaite uniquement sur certains spots.\nEn plus des classements, ou à leur place, un événement peut afficher des totaux sur tous les participants, par exemple les pumps ou la distance de toute l'équipe. Chaque événement a besoin d'au moins un classement ou un total.\nSeules les sessions qui commencent dans la fenêtre comptent.\nPour chaque événement, les responsables peuvent décider que les fichiers importés à la main (FIT, GPX, TCX) ne comptent pas ; les enregistrements de montres, de l'app et des comptes liés comptent toujours.\nAprès la fin, on peut encore envoyer des sessions pendant 4 heures ; la page de l'équipe affiche alors « résultats en attente ». Ensuite le résultat est figé, et un découpage ou une suppression ultérieurs ne changent plus rien.\nQui quitte l'équipe après la fin reste dans le résultat ; qui la rejoint ensuite n'y est plus ajouté.\nLes résultats sont figés la nuit, et aussi dès que quelqu'un ouvre la page de l'équipe.\nLes heures sont celles du fuseau horaire dans lequel l'événement a été créé et s'affichent ainsi pour tout le monde.\nLes places 1 à 3 reçoivent un badge d'événement sur leur page foiler, mais seulement pour les équipes dont l'apparence est validée.",
    "team.regeln.events.titel" to "Événements",
    "team.regeln.global.text" to "Les événements globaux sont organisés par pumpfoil.org lui-même. Toute personne ayant des sessions correspondantes dans la période compte automatiquement, sans adhésion ni inscription.\nCelui qui ne veut pas participer le désactive dans son profil sous « Confidentialité » (« Ne pas participer aux événements globaux »). Il disparaît alors des classements, classements d'équipe, totaux et badges, y compris des événements déjà terminés.\nChaque classement a un classement par équipe : la somme des meilleurs membres de chaque équipe, en général 5, et pour les vitesses (sprints) leur moyenne. Les équipes validées avec classements publics y participent. Qui est dans plusieurs équipes ne compte que pour une : celle choisie sur la page de l’événement, sinon son équipe principale (★, définie sur la page de l’équipe ou sous « Mes équipes »). Sans choix de ta part, rejoindre une autre équipe garde ton équipe actuelle comme principale : une équipe nouvelle ou devenue plus grande ne prend jamais la place d’elle-même. Tes équipes qui ne comptent pas (non validées ou classements non publics) apparaissent grisées sur la page de l’événement. Modifiable jusqu’à 6 heures avant la fin de l’événement.\nLes classements sont aussi visibles sans connexion via le lien de l'événement : rang, nom affiché, initiales et valeur.\nSinon, les règles des événements s'appliquent : période, évaluation, gel et badges pour les places 1 à 3, marqués « Global » sur la page de profil.",
    "team.regeln.global.titel" to "Événements globaux",
    "team.regeln.intro" to "Comment fonctionnent les équipes sur pumpfoil.org : qui voit quoi, comment on est classé et ce qui se passe lors d'une suppression.",
    "team.regeln.konto.text" to "La personne disparaît de toutes les équipes et de tous les classements, y compris des résultats d'événements figés. Les suivants remontent d'une place.\nSi elle dirigeait une équipe, le modérateur le plus ancien prend le relais, sinon le membre le plus ancien. S'il ne reste plus personne, l'équipe est supprimée.",
    "team.regeln.konto.titel" to "Quand un compte est supprimé",
    "team.regeln.link" to "Règles des équipes",
    "team.regeln.loeschen.text" to "Seul le responsable peut supprimer une équipe, et seulement en tapant le nom de l'équipe pour confirmer.\nL'équipe disparaît alors pour tout le monde : adhésions, classements, journal, événements et chat d'équipe. Nous gardons les données pour l'instant afin de pouvoir restaurer une équipe supprimée par erreur.\nL'adresse de l'équipe reste bloquée et n'est jamais attribuée à une autre équipe.",
    "team.regeln.loeschen.titel" to "Supprimer une équipe",
    "team.regeln.logbuch.text" to "Le journal note qui a battu quel record de l'équipe, et quand. Il est mis à jour chaque nuit.\nLa première entrée d'un classement est l'état lors de la première nuit après sa création.\nPour les meilleures valeurs, chaque amélioration compte, même la sienne propre. Pour les totaux, cela ne compte que lorsque quelqu'un prend la tête.\nSi un record baisse parce qu'une session a été supprimée ou que quelqu'un a quitté l'équipe, il est ajusté discrètement, sans entrée.",
    "team.regeln.logbuch.titel" to "Journal",
    "team.regeln.oeffentlich.text" to "En interne, une équipe peut tout faire. Elle n'apparaît à l'extérieur qu'une fois que nous avons vérifié et validé son nom, son adresse, sa description, son blason et sa couleur.\nLa bannière passe par la même validation que le blason. Les responsables choisissent la partie visible sans nouvelle validation ; s'ils retirent la bannière, elle disparaît aussitôt de la page publique aussi.\nSi une équipe validée modifie son apparence, cela s'applique tout de suite dans l'équipe, et en public après une nouvelle validation.\nLes équipes validées figurent sur la page « Toutes les équipes ». Leurs événements sont sur la page de l'équipe ; la communauté n'affiche que les événements globaux de pumpfoil.org.\nSi le responsable rend les classements publics, tout le monde les voit, même sans connexion, mais seulement le rang, le nom affiché, les initiales et la valeur. Les sessions, spots, dates et photos de profil ne sont visibles que pour les utilisateurs connectés.\nLes moteurs de recherche n'indexent pas les pages d'équipe.\nLe responsable décide qui voit la liste des membres : seulement les membres, ou tous les utilisateurs connectés.",
    "team.regeln.oeffentlich.titel" to "Ce qui est public",
    "team.regeln.rollen.text" to "Le responsable peut tout faire : paramètres, classements, événements, nommer des modérateurs, transmettre la responsabilité et supprimer l'équipe.\nLes modérateurs acceptent ou refusent les demandes, retirent des membres et créent des événements. Ils ne modifient rien d'autre.\nLes membres voient tout dans l'équipe et peuvent la quitter à tout moment.\nLe responsable ne peut quitter l'équipe qu'après avoir transmis la responsabilité.",
    "team.regeln.rollen.titel" to "Rôles",
    "team.regeln.statistik.text" to "Au-dessus des classements figurent les totaux de tous les membres sur la période choisie : pumps, distance et temps on-foil, sessions, runs et nombre de membres actifs.\nÉquipe contre équipe : dans la communauté, les classements d'équipes comparent toutes les équipes validées aux classements publics, pour chaque indicateur avec la somme des 3, 5 ou 10 meilleurs riders. La même mesure s'y applique à toutes les équipes, pas les filtres de leurs propres classements.\nQuelqu'un qui est dans deux équipes compte pour les deux.",
    "team.regeln.statistik.titel" to "Totaux de l'équipe",
    "team.regeln.titel" to "Règles des équipes",
    "team.regeln.was.text" to "Un groupe fixe avec ses propres classements, événements et un chat d'équipe.\nTout le monde peut créer des équipes, même plusieurs, et faire partie de plusieurs équipes.\nUne nouvelle équipe fonctionne tout de suite, via des liens d'invitation.",
    "team.regeln.was.titel" to "Qu'est-ce qu'une équipe ?",
    "team.rolle.leiter" to "Responsable",
    "team.rolle.mitglied" to "Membre",
    "team.rolle.moderator" to "Modérateur",
    "team.rolleUebergeben" to "Transmettre la responsabilité",
    "team.sichtbar.angemeldete" to "Tous les utilisateurs connectés",
