    "team.loeschenKnopf" to "Elimina definitivamente",
    "team.loeschenText" to "Il team scompare subito per tutti, con classifiche, eventi e chat del team. Per ora conserviamo i dati, così un team cancellato per errore si può ripristinare. Per confermare, digita il nome del team «{name}».",
