    "team.oeffentlichBadge" to "Classifiche pubbliche",
    "team.oeffentlichErstNachFreigabe" to "Ha effetto solo quando l'aspetto è approvato.",
    "team.oeffentlichText" to "Così tutti vedono le classifiche, anche senza accesso: posizione, nome visualizzato e valore. Sessioni, spot e foto profilo restano visibili solo agli utenti che hanno effettuato l'accesso.",
    "team.platz1" to "1º posto",
    "team.platz2" to "2º posto",
    "team.platz3" to "3º posto",
    "team.podest.fahrer" to "Rider",
    "team.podest.stumm" to "Muto",
    "team.podest.ton" to "Riproduci suono del vincitore",
    "team.primaer" to "Team principale",
    "team.primaerHinweis" to "Negli eventi globali conti per un solo team: il tuo team principale, a meno che tu non ne scelga un altro nella pagina dell’evento.",
    "team.primaerSetzen" to "Imposta come team principale",
    "team.profilHinweis" to "Crea team o unisciti, con classifiche proprie.",
    "team.profilKnopf" to "Team",
    "team.qr" to "Codice QR",
    "team.qrLaden" to "Salva codice QR",
    "team.qrTeilen" to "Condividi codice QR",
    "team.regeln.beitreten.text" to "Se un team consente le iscrizioni, la sua pagina mostra un pulsante «Unisciti». A seconda dell'impostazione sei subito membro, oppure decide il responsabile o un moderatore.\nCi sono due link d'invito: uno con cui diventi subito membro e uno con cui invii una richiesta. Entrambi sono disponibili anche come codice QR.\nChi non ha ancora un account ne crea uno e poi è subito nel team, oppure ha inviato la richiesta.\nUn nuovo link sostituisce quello vecchio, che da quel momento non funziona più.\nOgni volta che ti unisci, accetti che le classifiche del team possano essere pubbliche, anche se ora non lo sono.\nCon una richiesta, il responsabile e i moderatori vedono in quali spot e in quali sport sei stato finora (solo il numero di sessioni).",
    "team.regeln.beitreten.titel" to "Unirsi",
    "team.regeln.bestenlisten.text" to "Ogni persona conta una sola volta: il suo miglior valore in una sessione, oppure per i totali tutto quanto fatto nel periodo scelto, sommato.\nContano tutte le sessioni dei membri, anche quelle precedenti all'ingresso. Chi esce scompare subito dalle classifiche.\nPer gli eventi questo vale solo fino alla fine, vedi «Eventi».\nValgono gli stessi filtri dei record della community: le registrazioni eliminate, segnalate, non assegnate e in corso non contano.\nOgni classifica può essere limitata a uno sport, un intervallo di foil, le registrazioni con dati di movimento, il telefono sulla tavola o gli spot del team.\nSe «Nascondi il luogo» è attivo, la sessione non conta mai per uno spot specifico.\nIn caso di parità sta davanti chi ha ottenuto il valore per primo.",
    "team.regeln.bestenlisten.titel" to "Classifiche",
    "team.regeln.chat.text" to "Solo i membri attivi possono leggere e scrivere nella chat del team. Chi ha solo inviato una richiesta non la vede.\nNon compare da nessuna parte per gli altri, nemmeno tra le chat attive.\nChi esce o viene rimosso perde subito l'accesso e non riceve più notifiche.",
    "team.regeln.chat.titel" to "Chat del team",
    "team.regeln.events.text" to "Un evento ha una finestra di tempo e classifiche proprie, se si vuole solo in certi spot.\nOltre alle classifiche, o al loro posto, un evento può mostrare totali su tutti i partecipanti, come i pump o la distanza dell'intero team. Ogni evento richiede almeno una classifica o un totale.\nContano solo le sessioni che iniziano nella finestra.\nPer ogni evento il responsabile può decidere che i file caricati a mano (FIT, GPX, TCX) non contino; le registrazioni da orologi, app e account collegati contano comunque.\nDopo la fine si può ancora caricare per 4 ore; la pagina del team mostra allora «risultati in attesa». Poi il risultato è congelato, e ritagli o eliminazioni successivi non cambiano più nulla.\nChi esce dopo la fine resta nel risultato; chi entra dopo non viene più aggiunto.\nI risultati vengono congelati di notte e inoltre appena qualcuno apre la pagina del team.\nGli orari valgono nel fuso orario in cui è stato creato l'evento e vengono mostrati così a tutti.\nI posti da 1 a 3 ricevono un badge dell'evento sulla loro pagina foiler, ma solo nei team il cui aspetto è approvato.",
    "team.regeln.events.titel" to "Eventi",
    "team.regeln.global.text" to "Gli eventi globali li organizza pumpfoil.org stesso. Conta automaticamente chiunque abbia sessioni adatte nel periodo, senza entrare in un team e senza iscriversi.\nChi non vuole partecipare lo disattiva nel profilo sotto «Privacy» («Non partecipare agli eventi globali»). Allora sparisce da classifiche, classifiche dei team, totali e badge, anche negli eventi già conclusi.\nOgni classifica ha una classifica a squadre: la somma dei migliori membri di ogni team, di solito 5, e per le velocità (sprint) la loro media. Partecipano i team approvati con classifiche pubbliche. Chi è in più team conta per uno solo: quello scelto nella pagina dell’evento, altrimenti il suo team principale (★, impostato nella pagina del team o in «I miei team»). Senza una scelta propria, entrando in un altro team quello attuale resta il principale: un team nuovo o cresciuto non subentra mai da solo. I tuoi team che non contano (non approvati o con classifiche non pubbliche) appaiono in grigio nella pagina dell’evento. Si può cambiare fino a 6 ore prima della fine dell’evento.\nLe classifiche sono visibili anche senza accesso tramite il link dell'evento: posizione, nome visualizzato, iniziali e valore.\nPer il resto valgono le regole degli eventi: periodo, valutazione, congelamento e badge per i posti da 1 a 3, contrassegnati con «Global» sulla pagina profilo.",
    "team.regeln.global.titel" to "Eventi globali",
    "team.regeln.intro" to "Come funzionano i team su pumpfoil.org: chi vede cosa, come si viene classificati e cosa succede quando qualcosa viene eliminato.",
    "team.regeln.konto.text" to "La persona scompare da tutti i team e da tutte le classifiche, anche dai risultati degli eventi congelati. Chi sta sotto sale di posizione.\nSe guidava un team, subentra il moderatore con più anzianità, altrimenti il membro con più anzianità. Se non resta nessuno, il team viene eliminato.",
    "team.regeln.konto.titel" to "Quando un account viene eliminato",
    "team.regeln.link" to "Regole dei team",
    "team.regeln.loeschen.text" to "Solo il responsabile può eliminare un team, e solo digitando il nome del team per conferma.\nIl team sparisce allora per tutti: iscrizioni, classifiche, diario di bordo, eventi e chat del team. Per ora conserviamo i dati, così un team cancellato per errore si può ripristinare.\nL'indirizzo del team resta bloccato e non viene mai assegnato a un altro team.",
    "team.regeln.loeschen.titel" to "Eliminare un team",
    "team.regeln.logbuch.text" to "Il diario di bordo registra chi ha battuto quale record del team, e quando. Viene aggiornato ogni notte.\nLa prima voce di una classifica è la situazione nella prima notte dopo la sua creazione.\nPer i migliori valori conta ogni miglioramento, anche il proprio. Per i totali conta solo quando qualcuno passa in testa.\nSe un record scende perché è stata eliminata una sessione o qualcuno è uscito, viene adeguato in silenzio, senza una voce.",
    "team.regeln.logbuch.titel" to "Diario di bordo",
    "team.regeln.oeffentlich.text" to "All'interno un team può fare tutto. All'esterno compare solo dopo che abbiamo controllato e approvato nome, indirizzo, descrizione, stemma e colore.\nL'immagine del team passa per la stessa approvazione dello stemma. Quale parte si vede lo sceglie il responsabile senza nuova approvazione; se la rimuove, sparisce subito anche dalla pagina pubblica.\nSe un team approvato cambia il suo aspetto, la modifica vale subito all'interno del team, all'esterno solo dopo una nuova approvazione.\nI team approvati sono elencati nella pagina «Tutti i team». I loro eventi sono sulla pagina del team; nella community compaiono solo gli eventi globali di pumpfoil.org.\nSe il responsabile rende pubbliche le classifiche, tutti le vedono, anche senza accesso, ma solo posizione, nome visualizzato, iniziali e valore. Sessioni, spot, date e foto profilo sono visibili solo agli utenti che hanno effettuato l'accesso.\nI motori di ricerca non indicizzano le pagine dei team.\nIl responsabile decide chi vede l'elenco dei membri: solo i membri o tutti gli utenti con accesso.",
    "team.regeln.oeffentlich.titel" to "Cosa è pubblico",
    "team.regeln.rollen.text" to "Il responsabile può fare tutto: impostazioni, classifiche, eventi, nominare moderatori, cedere la guida ed eliminare il team.\nI moderatori accettano o rifiutano le richieste, rimuovono membri e creano eventi. Non modificano nient'altro.\nI membri vedono tutto nel team e possono uscire in qualsiasi momento.\nIl responsabile può uscire solo dopo aver ceduto la guida.",
    "team.regeln.rollen.titel" to "Ruoli",
    "team.regeln.statistik.text" to "Sopra le classifiche ci sono i totali di tutti i membri nel periodo scelto: pumps, distanza e tempo on-foil, sessioni, run e quanti membri sono stati attivi.\nTeam contro team: nella community le classifiche dei team confrontano tutti i team approvati con classifiche pubbliche, per ogni metrica con la somma dei migliori 3, 5 o 10 rider. Lì vale per tutti i team la stessa misura, non i filtri delle proprie classifiche.\nChi è in due team conta per entrambi.",
    "team.regeln.statistik.titel" to "Totali del team",
    "team.regeln.titel" to "Regole dei team",
    "team.regeln.was.text" to "Un gruppo fisso con classifiche proprie, eventi e una chat del team.\nChiunque può creare team, anche più di uno, e far parte di più team.\nUn nuovo team funziona subito, tramite link d'invito.",
    "team.regeln.was.titel" to "Cos'è un team?",
    "team.rolle.leiter" to "Responsabile",
    "team.rolle.mitglied" to "Membro",
    "team.rolle.moderator" to "Moderatore",
    "team.rolleUebergeben" to "Cedi la guida",
    "team.sichtbar.angemeldete" to "Tutti gli utenti con accesso",
