    "team.spotWaehlen" to "Scegli uno spot …",
    "team.spots" to "Spot del team",
    "team.spotsHinweis" to "Le classifiche impostate su «solo spot del team» contano solo le sessioni in questi spot.",
    "team.stat.aktiv" to "attivi",
    "team.stat.laeufe" to "Run",
