    "team.bestenlistenHinweis" to "De cada persona cuenta su mejor valor o su total en el periodo elegido. Cuentan todas las sesiones de los miembros, también las de antes de unirse.",
    "team.bild.hinweisIntern" to "Las clasificaciones de este equipo no son públicas. Aun así, la imagen muestra los nombres a cualquiera que la vea.",
