    "team.loeschenKnopf" to "Eliminar definitivamente",
    "team.loeschenText" to "El equipo desaparece al instante para todos, con sus clasificaciones, eventos y chat del equipo. De momento guardamos los datos para poder restaurar un equipo borrado por error. Para confirmar, escribe el nombre del equipo «{name}».",
    "team.logbuch" to "Bitácora",
    "team.logbuch.gebrochen" to "{name} bate «{was}» con {wert} (antes: {vorher}, {vorherWert})",
    "team.logbuch.start" to "{name} tiene «{was}» con {wert}",
    "team.logbuchHinweis" to "Quién batió qué récord del equipo y cuándo. Se actualiza cada noche.",
    "team.logbuchLeer" to "Aún no hay entradas. El primer estado aparece la noche después de crear las clasificaciones.",
    "team.logoHochladen" to "Subir escudo",
    "team.meine" to "Mis equipos",
    "team.mitglieder" to "Miembros",
    "team.mitgliederAnzahl" to "{n} miembros",
    "team.mitgliederSichtbar" to "¿Quién ve la lista de miembros?",
    "team.name" to "Nombre del equipo",
    "team.nichtGefunden" to "Este equipo no existe o no es público.",
    "team.nurFuerMitglieder" to "Solo los miembros ven las clasificaciones de este equipo.",
    "team.oeffentlich" to "Clasificaciones públicas",
    "team.oeffentlichBadge" to "Clasificaciones públicas",
    "team.oeffentlichErstNachFreigabe" to "Solo tiene efecto cuando la apariencia esté aprobada.",
    "team.oeffentlichText" to "Así cualquiera ve las clasificaciones, incluso sin iniciar sesión: puesto, nombre visible y valor. Las sesiones, los spots y las fotos de perfil solo los ven los usuarios con sesión iniciada.",
    "team.platz1" to "1.er puesto",
    "team.platz2" to "2.º puesto",
    "team.platz3" to "3.er puesto",
    "team.podest.fahrer" to "Riders",
    "team.podest.stumm" to "Silenciar",
    "team.podest.ton" to "Reproducir sonido del ganador",
    "team.primaer" to "Equipo principal",
    "team.primaerHinweis" to "En los eventos globales solo cuentas para un equipo: tu equipo principal, salvo que elijas otro en la página del evento.",
    "team.primaerSetzen" to "Fijar como equipo principal",
    "team.profilHinweis" to "Crea equipos o únete a ellos, con sus propias clasificaciones.",
    "team.profilKnopf" to "Equipo",
    "team.qr" to "Código QR",
    "team.qrLaden" to "Guardar código QR",
    "team.qrTeilen" to "Compartir código QR",
    "team.regeln.beitreten.text" to "Si un equipo admite solicitudes de ingreso, su página muestra un botón «Unirse». Según el ajuste, eres miembro al instante, o decide el líder o un moderador.\nHay dos enlaces de invitación: uno con el que eres miembro al instante y otro con el que envías una solicitud. Ambos existen también como código QR.\nQuien aún no tiene cuenta crea una y después ya está en el equipo o ha enviado la solicitud.\nUn enlace nuevo sustituye al anterior, que deja de funcionar.\nCada vez que te unes, aceptas que las clasificaciones del equipo puedan ser públicas, aunque ahora no lo sean.\nCon una solicitud, el líder y los moderadores ven en qué spots y deportes has estado hasta ahora (solo el número de sesiones).",
    "team.regeln.beitreten.titel" to "Unirse",
    "team.regeln.bestenlisten.text" to "Cada persona cuenta una sola vez: su mejor valor en una sesión o, en los totales, todo lo del periodo elegido sumado.\nCuentan todas las sesiones de los miembros, también las de antes de unirse. Quien sale desaparece al instante de las listas.\nEn los eventos esto solo vale hasta el final, ver «Eventos».\nSe aplican los mismos filtros que en los récords de la comunidad: no cuentan las grabaciones eliminadas, denunciadas, sin asignar ni en curso.\nCada clasificación puede limitarse a un deporte, un rango de foils, grabaciones con datos de movimiento, el teléfono en la tabla o los spots del equipo.\nSi «Ocultar el lugar» está activado, la sesión nunca cuenta para un spot concreto.\nEn caso de empate, va delante quien consiguió el valor primero.",
    "team.regeln.bestenlisten.titel" to "Clasificaciones",
    "team.regeln.chat.text" to "Solo los miembros activos pueden leer y escribir en el chat del equipo. Quien solo ha enviado una solicitud no lo ve.\nNo aparece en ningún sitio para los demás, ni siquiera entre los chats activos.\nQuien sale o es quitado pierde el acceso al instante y ya no recibe notificaciones.",
    "team.regeln.chat.titel" to "Chat del equipo",
    "team.regeln.events.text" to "Un evento tiene una franja de tiempo y sus propias clasificaciones, si se quiere solo en ciertos spots.\nAdemás de las clasificaciones, o en su lugar, un evento puede mostrar totales de todos los participantes, como los pumps o la distancia de todo el equipo. Cada evento necesita al menos una clasificación o un total.\nSolo cuentan las sesiones que empiezan dentro de la franja.\nEn cada evento, el líder puede decidir que no cuenten los archivos subidos a mano (FIT, GPX, TCX); las grabaciones de relojes, la app y cuentas vinculadas siguen contando.\nTras el final aún se puede subir durante 4 horas; la página del equipo muestra entonces «resultados pendientes». Después el resultado queda congelado, y recortar o eliminar más tarde ya no cambia nada.\nQuien sale después del final sigue en el resultado; quien se une después ya no entra.\nLos resultados se congelan por la noche y además en cuanto alguien abre la página del equipo.\nLas horas valen en la zona horaria en la que se creó el evento y se muestran así a todos.\nLos puestos 1 a 3 reciben una insignia del evento en su página de foiler, pero solo en equipos cuya apariencia está aprobada.",
    "team.regeln.events.titel" to "Eventos",
    "team.regeln.global.text" to "Los eventos globales los organiza el propio pumpfoil.org. Cuenta automáticamente cualquiera con sesiones adecuadas en el periodo, sin unirse ni inscribirse.\nQuien no quiera participar lo desactiva en su perfil, en «Privacidad» («No participar en eventos globales»). Entonces desaparece de clasificaciones, clasificaciones de equipo, totales e insignias, también en eventos ya terminados.\nCada clasificación tiene una clasificación por equipos: la suma de los mejores miembros de cada equipo, normalmente 5, y en las velocidades (sprints) su media. Participan los equipos aprobados con clasificaciones públicas. Quien está en varios equipos cuenta solo para uno: el elegido en la página del evento; si no, su equipo principal (★, fijado en la página del equipo o en «Mis equipos»). Sin elección propia, al unirte a otro equipo tu equipo actual sigue siendo el principal: un equipo nuevo o que ha crecido nunca toma el relevo por sí solo. Tus equipos que no cuentan (no aprobados o con clasificaciones no públicas) aparecen en gris en la página del evento. Se puede cambiar hasta 6 horas antes del final del evento.\nLas clasificaciones también se ven sin iniciar sesión mediante el enlace del evento: puesto, nombre visible, iniciales y valor.\nPor lo demás se aplican las reglas de los eventos: periodo, evaluación, congelación e insignias para los puestos 1 a 3, marcadas con «Global» en la página de perfil.",
    "team.regeln.global.titel" to "Eventos globales",
    "team.regeln.intro" to "Así funcionan los equipos en pumpfoil.org: quién ve qué, cómo se puntúa y qué pasa al eliminar algo.",
    "team.regeln.konto.text" to "La persona desaparece de todos los equipos y clasificaciones, y también de los resultados de eventos congelados. Los puestos de debajo suben.\nSi lideraba un equipo, toma el relevo el moderador más antiguo y, si no hay, el miembro más antiguo. Si no queda nadie, el equipo se elimina.",
    "team.regeln.konto.titel" to "Cuando se elimina una cuenta",
    "team.regeln.link" to "Reglas de los equipos",
    "team.regeln.loeschen.text" to "Solo el líder puede eliminar un equipo, y solo escribiendo el nombre del equipo para confirmar.\nEntonces el equipo desaparece para todos: membresías, clasificaciones, bitácora, eventos y chat del equipo. De momento guardamos los datos para poder restaurar un equipo borrado por error.\nLa dirección del equipo queda bloqueada y nunca se asigna a otro equipo.",
    "team.regeln.loeschen.titel" to "Eliminar un equipo",
    "team.regeln.logbuch.text" to "La bitácora registra quién batió qué récord del equipo y cuándo. Se actualiza cada noche.\nLa primera entrada de una clasificación es el estado de la primera noche después de crearla.\nEn los mejores valores cuenta cada mejora, también la propia. En los totales solo cuenta cuando alguien pasa a liderar.\nSi un récord baja porque se eliminó una sesión o alguien salió, se ajusta en silencio, sin entrada.",
    "team.regeln.logbuch.titel" to "Bitácora",
    "team.regeln.oeffentlich.text" to "Dentro, un equipo puede hacer de todo. Hacia fuera solo aparece cuando hemos revisado y aprobado su nombre, dirección, descripción, escudo y color.\nLa imagen del equipo pasa por la misma aprobación que el escudo. Qué parte se ve lo elige el líder sin nueva aprobación; si la quita, desaparece al instante también de la página pública.\nSi un equipo aprobado cambia su apariencia, se aplica al instante dentro del equipo y, en público, tras una nueva aprobación.\nLos equipos aprobados aparecen en la página «Todos los equipos». Sus eventos están en la página del equipo; en la comunidad solo aparecen los eventos globales de pumpfoil.org.\nSi el líder hace públicas las clasificaciones, cualquiera las ve, incluso sin iniciar sesión, pero solo el puesto, el nombre visible, las iniciales y el valor. Las sesiones, los spots, las fechas y las fotos de perfil solo los ven los usuarios con sesión iniciada.\nLos buscadores no indexan las páginas de equipos.\nEl líder decide quién ve la lista de miembros: solo los miembros o todos los usuarios con sesión iniciada.",
    "team.regeln.oeffentlich.titel" to "Qué es público",
    "team.regeln.rollen.text" to "El líder puede hacerlo todo: ajustes, clasificaciones, eventos, nombrar moderadores, ceder el liderazgo y eliminar el equipo.\nLos moderadores aceptan o rechazan solicitudes, quitan miembros y crean eventos. No cambian nada más.\nLos miembros ven todo en el equipo y pueden salir en cualquier momento.\nEl líder solo puede salir después de ceder el liderazgo.",
    "team.regeln.rollen.titel" to "Roles",
    "team.regeln.statistik.text" to "Encima de las clasificaciones están los totales de todos los miembros en el periodo elegido: pumps, distancia y tiempo on-foil, sesiones, runs y cuántos miembros estuvieron activos.\nEquipo contra equipo: en la comunidad, las clasificaciones de equipos comparan todos los equipos aprobados con clasificaciones públicas, en cada métrica con la suma de los mejores 3, 5 o 10 riders. Allí se aplica la misma medida a todos los equipos, no los filtros de sus propias clasificaciones.\nQuien está en dos equipos cuenta para ambos.",
    "team.regeln.statistik.titel" to "Totales del equipo",
    "team.regeln.titel" to "Reglas de los equipos",
    "team.regeln.was.text" to "Un grupo fijo con sus propias clasificaciones, eventos y un chat del equipo.\nCualquiera puede crear equipos, también varios, y estar en varios equipos.\nUn equipo nuevo funciona al instante, con enlaces de invitación.",
    "team.regeln.was.titel" to "¿Qué es un equipo?",
    "team.rolle.leiter" to "Líder",
    "team.rolle.mitglied" to "Miembro",
    "team.rolle.moderator" to "Moderador",
    "team.rolleUebergeben" to "Ceder el liderazgo",
    "team.sichtbar.angemeldete" to "Todos los usuarios con sesión iniciada",
    "team.sichtbar.mitglieder" to "Solo miembros",
    "team.sichtbarkeit" to "Visibilidad",
    "team.spotHinzu" to "Añadir",
    "team.spotWaehlen" to "Elige un spot …",
    "team.spots" to "Spots del equipo",
