    "team.regeln.beitreten.text" to "Jos tiimi ottaa vastaan ilmoittautumisia, sen sivulla on ”Liity”-painike. Asetuksesta riippuen olet heti jäsen, tai vetäjä tai moderaattori päättää.\nKutsulinkkejä on kaksi: toisella pääset heti jäseneksi, toisella lähetät pyynnön. Molemmat ovat saatavilla myös QR-koodina.\nJos tiliä ei vielä ole, sen voi luoda, ja sen jälkeen on heti tiimissä tai on lähettänyt pyynnön.\nUusi luotu linkki korvaa vanhan, joka ei sen jälkeen enää toimi.\nJoka kerta liittyessäsi hyväksyt, että tiimin tulostaulukot voivat olla julkisia, vaikka ne eivät juuri nyt olisi.\nPyynnön yhteydessä vetäjä ja moderaattorit näkevät, millä spoteilla ja missä lajeissa olet tähän asti liikkunut (vain sessioiden määrän).",
    "team.regeln.beitreten.titel" to "Liittyminen",
    "team.regeln.bestenlisten.text" to "Jokaiselta lasketaan vain yksi merkintä: paras tulos yhdestä sessiosta tai summissa kaikki valitulta ajalta yhteensä.\nKaikki jäsenten sessiot lasketaan, myös ennen liittymistä ajetut. Tiimistä eroava katoaa taulukoista heti.\nTapahtumissa tämä pätee vain loppuun asti, katso ”Tapahtumat”.\nSamat suodattimet pätevät kuin yhteisön ennätyksissä: poistettuja, ilmiannettuja, lajiin luokittelemattomia ja käynnissä olevia tallennuksia ei lasketa.\nJokaisen tulostaulukon voi rajata yhteen lajiin, yhteen foilialueeseen, tallennuksiin, joissa on liiketiedot, puhelimeen laudalla tai tiimin spotteihin.\nJos ”Piilota paikka” on päällä, sessiota ei koskaan lasketa tietylle spotille.\nTasatilanteessa edellä on se, joka ajoi tuloksen ensin.",
    "team.regeln.bestenlisten.titel" to "Tulostaulukot",
    "team.regeln.chat.text" to "Tiimichattia lukevat ja siihen kirjoittavat vain aktiiviset jäsenet. Pelkän pyynnön lähettänyt ei näe sitä.\nMuille se ei näy missään, ei edes aktiivisten chattien joukossa.\nTiimistä eroava tai poistettu menettää pääsyn heti eikä saa enää ilmoituksia.",
    "team.regeln.chat.titel" to "Tiimichat",
    "team.regeln.events.text" to "Tapahtumalla on aikaikkuna ja omat tulostaulukot, halutessa vain tietyillä spoteilla.\nTulostaulukoiden lisäksi tai sijaan tapahtuma voi näyttää kaikkien osallistujien yhteissummia, esimerkiksi koko tiimin pumppaukset tai matkan. Jokainen tapahtuma tarvitsee vähintään yhden tulostaulukon tai yhteissumman.\nMukaan lasketaan vain sessiot, jotka alkavat aikaikkunan sisällä.\nVetäjä voi päättää tapahtumakohtaisesti, ettei käsin ladattuja tiedostoja (FIT, GPX, TCX) lasketa; kellojen, sovelluksen ja yhdistettyjen tilien tallenteet lasketaan edelleen.\nLopun jälkeen voi vielä 4 tuntia ladata sessioita, ja tiimisivulla näkyy silloin ”tulokset tulossa”. Sen jälkeen tulos jäädytetään, eikä myöhempi rajaus tai poisto enää muuta mitään.\nLopun jälkeen eroava pysyy tuloksissa; myöhemmin liittyvä ei enää tule mukaan.\nJäädytys tehdään öisin ja lisäksi heti, kun joku avaa tiimisivun.\nAjat ovat sen aikavyöhykkeen mukaisia, jossa tapahtuma luotiin, ja ne näytetään kaikille samoin.\nSijat 1–3 saavat tapahtumamerkin foilaajasivulleen, mutta vain tiimeissä, joiden ulkoasu on hyväksytty.",
    "team.regeln.events.titel" to "Tapahtumat",
    "team.regeln.global.text" to "Globaalit tapahtumat järjestää pumpfoil.org itse. Jokainen, jolla on sopivia sessioita aikaikkunassa, lasketaan automaattisesti mukaan, ilman liittymistä ja ilmoittautumista.\nJoka ei halua osallistua, kytkee sen pois profiilissa kohdassa ”Yksityisyys” (”Älä osallistu globaaleihin tapahtumiin”). Silloin hän puuttuu tulostauluilta, tiimipisteistä, summista ja merkeistä, myös jo päättyneistä tapahtumista.\nJokaisella tulostaululla on tiimien sarja: kunkin tiimin parhaiden jäsenten summa, yleensä 5, ja nopeuksissa (sprintit) heidän keskiarvonsa. Mukana ovat hyväksytyt tiimit, joiden tulostaulut ovat julkisia. Useassa tiimissä oleva lasketaan vain yhteen: tapahtuman sivulla valittuun, muuten ensisijaiseen tiimiinsä (★, asetetaan tiimin sivulla tai kohdassa ”Omat tiimit”). Ilman omaa valintaa nykyinen tiimi pysyy ensisijaisena, kun liityt uuteen tiimiin – uusi tai kasvanut tiimi ei koskaan ota paikkaa itsestään. Omat tiimit, jotka eivät ole mukana laskennassa (ei hyväksytty tai tulostaulut eivät julkisia), näkyvät tapahtuman sivulla harmaina. Valintaa voi muuttaa 6 tuntiin asti ennen tapahtuman loppua.\nTulostaulut näkyvät myös kirjautumatta tapahtumalinkin kautta: sija, näyttönimi, nimikirjaimet ja arvo.\nMuuten pätevät tapahtumien säännöt: aikaikkuna, tulosten laskenta, jäädytys ja merkit sijoille 1–3, profiilisivulla merkinnällä ”Global”.",
    "team.regeln.global.titel" to "Globaalit tapahtumat",
    "team.regeln.intro" to "Näin tiimit toimivat pumpfoil.orgissa: kuka näkee mitä, miten tulokset lasketaan ja mitä poistaessa tapahtuu.",
    "team.regeln.konto.text" to "Henkilö katoaa kaikista tiimeistä ja tulostaulukoista, myös jäädytetyistä tapahtumatuloksista. Alempana olevat nousevat sijan ylöspäin.\nJos hän veti tiimiä, vetovastuun ottaa pisimpään toiminut moderaattori, muuten pisimpään mukana ollut jäsen. Jos ketään ei ole jäljellä, tiimi poistetaan.",
    "team.regeln.konto.titel" to "Kun tili poistetaan",
    "team.regeln.link" to "Tiimien säännöt",
    "team.regeln.loeschen.text" to "Tiimin voi poistaa vain vetäjä, ja vain kirjoittamalla vahvistukseksi tiimin nimen.\nSilloin tiimi katoaa kaikilta: jäsenyydet, tulostaulukot, lokikirja, tapahtumat ja tiimichat. Säilytämme tiedot toistaiseksi, jotta vahingossa poistettu tiimi voidaan palauttaa.\nTiimin osoite pysyy varattuna eikä sitä koskaan anneta toiselle tiimille.",
    "team.regeln.loeschen.titel" to "Tiimin poistaminen",
    "team.regeln.logbuch.text" to "Lokikirja kirjaa, kuka rikkoi minkäkin tiimiennätyksen ja milloin. Se päivittyy joka yö.\nTulostaulukon ensimmäinen merkintä on tilanne ensimmäisenä yönä sen luomisen jälkeen.\nParhaissa tuloksissa lasketaan jokainen parannus, myös oma. Summissa lasketaan vain se, kun joku nousee kärkeen.\nJos ennätys laskee siksi, että sessio poistettiin tai joku erosi, se korjataan hiljaa ilman merkintää.",
    "team.regeln.logbuch.titel" to "Lokikirja",
    "team.regeln.oeffentlich.text" to "Sisäisesti tiimi saa tehdä mitä vain. Muille se näkyy vasta, kun olemme kerran katsoneet ja hyväksyneet sen nimen, osoitteen, kuvauksen, tunnuksen ja värin.\nTiimin banneri käy läpi saman hyväksynnän kuin tunnus. Näkyvän osan valitsee vetäjä ilman uutta hyväksyntää; jos banneri poistetaan, se katoaa heti myös julkiselta sivulta.\nJos hyväksytty tiimi muuttaa ulkoasuaan, muutos näkyy tiimissä heti ja muille vasta uuden hyväksynnän jälkeen.\nHyväksytyt tiimit näkyvät sivulla ”Kaikki tiimit”. Niiden tapahtumat ovat tiimisivulla; yhteisössä näkyvät vain pumpfoil.orgin globaalit tapahtumat.\nJos vetäjä avaa tulostaulukot julkisiksi, kuka tahansa näkee ne ilman kirjautumista, mutta vain sijan, näyttönimen, nimikirjaimet ja tuloksen. Sessiot, spotit, päivämäärät ja profiilikuvat näkyvät vain kirjautuneille.\nHakukoneet eivät indeksoi tiimisivuja.\nVetäjä päättää, kuka näkee jäsenluettelon: vain jäsenet vai kaikki kirjautuneet.",
    "team.regeln.oeffentlich.titel" to "Mikä on julkista",
    "team.regeln.rollen.text" to "Vetäjä saa tehdä kaiken: asetukset, tulostaulukot, tapahtumat, moderaattorien nimeämisen, vetovastuun luovuttamisen ja tiimin poistamisen.\nModeraattorit hyväksyvät tai hylkäävät pyyntöjä, poistavat jäseniä ja luovat tapahtumia. Muuta he eivät muuta.\nJäsenet näkevät tiimissä kaiken ja voivat erota milloin tahansa.\nVetäjä voi erota vasta luovutettuaan vetovastuun.",
    "team.regeln.rollen.titel" to "Roolit",
    "team.regeln.statistik.text" to "Tulostaulukoiden yläpuolella ovat kaikkien jäsenten summat valitulta ajalta: pumppaukset, foil-matka ja foil-aika, sessiot, lenkit ja montako jäsentä oli aktiivisia.\nTiimi vastaan tiimi: yhteisössä tiimien tulostaulut vertaavat kaikkia hyväksyttyjä tiimejä, joilla on julkiset tulostaulut, jokaisessa mittarissa parhaan 3, 5 tai 10 ajajan summalla. Siellä kaikkia tiimejä mitataan samalla tavalla, ei niiden omien tulostaulujen suodattimilla.\nKahdessa tiimissä oleva lasketaan molempiin.",
    "team.regeln.statistik.titel" to "Tiimin summat",
    "team.regeln.titel" to "Tiimien säännöt",
    "team.regeln.was.text" to "Pysyvä ryhmä, jolla on omat tulostaulukot, tapahtumat ja tiimichat.\nKuka tahansa voi perustaa tiimejä, myös useita, ja kuulua useaan tiimiin.\nUusi tiimi toimii heti kutsulinkkien kautta.",
    "team.regeln.was.titel" to "Mikä on tiimi?",
    "team.rolle.leiter" to "Vetäjä",
