    "team.loeschenKnopf" to "Definitief verwijderen",
    "team.loeschenText" to "Het team verdwijnt meteen voor iedereen, met ranglijsten, events en teamchat. We bewaren de gegevens voorlopig, zodat een per ongeluk verwijderd team terug te halen is. Typ ter bevestiging de teamnaam „{name}”.",
