    "team.oeffentlichErstNachFreigabe" to "Werkt pas als het uiterlijk is vrijgegeven.",
    "team.oeffentlichText" to "Dan ziet iedereen de ranglijsten, ook zonder in te loggen: plaats, weergavenaam en waarde. Sessies, spots en profielfoto's blijven alleen zichtbaar voor ingelogde gebruikers.",
