    "team.podest.fahrer" to "Riders",
    "team.podest.stumm" to "Dempen",
    "team.podest.ton" to "Winnaarsgeluid afspelen",
    "team.primaer" to "Primair team",
    "team.primaerHinweis" to "Bij globale events tel je maar voor één team: je primaire team, tenzij je op de eventpagina een ander kiest.",
    "team.primaerSetzen" to "Als primair team instellen",
    "team.profilHinweis" to "Teams oprichten, lid worden en eigen ranglijsten bijhouden.",
    "team.profilKnopf" to "Team",
    "team.qr" to "QR-code",
    "team.qrLaden" to "QR-code opslaan",
    "team.qrTeilen" to "QR-code delen",
    "team.regeln.beitreten.text" to "Staat een team aanmeldingen toe, dan staat op de teampagina een knop „Lid worden”. Afhankelijk van de instelling ben je meteen lid, of beslist de leiding of een moderator.\nEr zijn twee uitnodigingslinks: een waarmee je meteen lid bent en een waarmee je een verzoek stuurt. Beide zijn er ook als QR-code.\nWie nog geen account heeft, maakt er een aan en zit daarna direct in het team of heeft het verzoek gestuurd.\nEen nieuw aangemaakte link vervangt de oude, die daarna niet meer werkt.\nBij elke keer dat je lid wordt, ga je ermee akkoord dat de ranglijsten van het team openbaar kunnen zijn, ook als ze dat nu niet zijn.\nBij een verzoek zien de leiding en de moderators op welke spots en in welke sporten je tot nu toe bent geweest (alleen het aantal sessies).",
    "team.regeln.beitreten.titel" to "Lid worden",
    "team.regeln.bestenlisten.text" to "Per persoon telt maar één vermelding: de beste waarde uit één sessie, of bij totalen alles in de gekozen periode bij elkaar.\nAlle sessies van de leden tellen mee, ook die van vóór het lidmaatschap. Wie vertrekt, verdwijnt meteen uit de lijsten.\nBij events geldt dat alleen tot het einde, zie „Events”.\nDezelfde filters gelden als bij de community-records: verwijderde, gemelde, niet toegewezen en lopende opnames tellen niet mee.\nElke ranglijst kan worden beperkt tot een sport, een foilbereik, opnames met bewegingsdata, de telefoon op de plank of de teamspots.\nStaat „Locatie verbergen” aan, dan telt de sessie nooit mee voor een bepaalde spot.\nBij gelijke stand staat voorop wie de waarde het eerst heeft gereden.",
    "team.regeln.bestenlisten.titel" to "Ranglijsten",
    "team.regeln.chat.text" to "Alleen actieve leden kunnen de teamchat lezen en erin schrijven. Wie alleen een verzoek heeft gestuurd, ziet hem niet.\nHij verschijnt voor anderen nergens, ook niet tussen de actieve chats.\nWie vertrekt of wordt verwijderd, verliest meteen de toegang en krijgt geen meldingen meer.",
    "team.regeln.chat.titel" to "Teamchat",
    "team.regeln.events.text" to "Een event heeft een tijdvak en eigen ranglijsten, desgewenst alleen op bepaalde spots.\nNaast of in plaats van ranglijsten kan een event totalen over alle deelnemers tonen, zoals de pumps of de afstand van het hele team. Elk event heeft minstens één ranglijst of één totaal nodig.\nAlleen sessies die binnen het tijdvak starten tellen mee.\nPer event kan de leiding bepalen dat handmatig geüploade bestanden (FIT, GPX, TCX) niet tellen; opnames van horloges, de app en gekoppelde accounts tellen dan nog wel.\nNa het einde kun je nog 4 uur uploaden; de teampagina toont dan „uitslag volgt”. Daarna is de uitslag bevroren en verandert later bijsnijden of verwijderen niets meer.\nWie na het einde vertrekt, blijft in de uitslag; wie daarna lid wordt, komt er niet meer bij.\nUitslagen worden 's nachts bevroren en ook zodra iemand de teampagina opent.\nDe tijden gelden in de tijdzone waarin het event is aangemaakt en worden voor iedereen zo getoond.\nPlaats 1 tot 3 krijgen een event-badge op hun foilerpagina, maar alleen bij teams waarvan het uiterlijk is vrijgegeven.",
    "team.regeln.events.titel" to "Events",
    "team.regeln.global.text" to "Globale events organiseert pumpfoil.org zelf. Iedereen met passende sessies in het tijdvak telt automatisch mee, zonder lid te worden en zonder aanmelding.\nWie niet mee wil doen, zet het uit in zijn profiel onder „Privacy” („Niet meedoen aan globale events”). Dan ontbreekt hij in ranglijsten, teamstanden, totalen en badges, ook in events die al voorbij zijn.\nElke ranglijst heeft een teamklassement: de som van de beste leden van elk team, meestal 5, en bij snelheden (sprints) hun gemiddelde. Goedgekeurde teams met openbare ranglijsten doen mee. Wie in meerdere teams zit, telt maar voor één: het team dat op de eventpagina is gekozen, anders het primaire team (★, in te stellen op de teampagina of bij „Mijn teams”). Zonder eigen keuze blijft bij het lid worden van een ander team het huidige team het primaire – een nieuw of gegroeid team neemt het nooit vanzelf over. Eigen teams die niet meetellen (niet goedgekeurd of ranglijsten niet openbaar) staan grijs op de eventpagina. Dit kan tot 6 uur voor het einde van het event worden gewijzigd.\nDe ranglijsten zijn ook zonder inloggen zichtbaar via de eventlink: plaats, weergavenaam, initialen en waarde.\nVerder gelden de regels voor events: tijdvak, uitslag, bevriezen en badges voor plaats 1 tot 3, op de profielpagina gemarkeerd met „Global”.",
    "team.regeln.global.titel" to "Globale events",
    "team.regeln.intro" to "Zo werken teams op pumpfoil.org: wie wat ziet, hoe er gerangschikt wordt en wat er gebeurt als iets wordt verwijderd.",
    "team.regeln.konto.text" to "De persoon verdwijnt uit alle teams en ranglijsten, en ook uit bevroren event-uitslagen. De plaatsen eronder schuiven op.\nLeidde die persoon een team, dan neemt de moderator die het langst lid is het over, anders het lid dat het langst lid is. Is er niemand meer, dan wordt het team verwijderd.",
    "team.regeln.konto.titel" to "Als een account wordt verwijderd",
    "team.regeln.link" to "Teamregels",
    "team.regeln.loeschen.text" to "Alleen de leiding kan een team verwijderen, en alleen door ter bevestiging de teamnaam in te typen.\nDan is het team voor iedereen weg: lidmaatschappen, ranglijsten, logboek, events en de teamchat. We bewaren de gegevens voorlopig, zodat een per ongeluk verwijderd team terug te halen is.\nHet adres van het team blijft geblokkeerd en wordt nooit aan een ander team gegeven.",
    "team.regeln.loeschen.titel" to "Team verwijderen",
    "team.regeln.logbuch.text" to "Het logboek houdt bij wie wanneer welk teamrecord heeft gebroken. Het wordt elke nacht bijgewerkt.\nDe eerste vermelding van een ranglijst is de stand in de eerste nacht na het aanmaken.\nBij beste waarden telt elke verbetering, ook die van jezelf. Bij totalen telt het alleen als iemand de leiding overneemt.\nDaalt een record omdat een sessie is verwijderd of iemand is vertrokken, dan wordt dat stil bijgewerkt, zonder vermelding.",
    "team.regeln.logbuch.titel" to "Logboek",
    "team.regeln.oeffentlich.text" to "Intern mag een team alles. Naar buiten verschijnt het pas als wij naam, adres, beschrijving, embleem en kleur hebben bekeken en vrijgegeven.\nDe teambanner gaat door dezelfde goedkeuring als het embleem. Welk deel zichtbaar is, kiest de leiding zonder nieuwe goedkeuring; haalt zij de banner weg, dan verdwijnt hij meteen ook van de openbare pagina.\nWijzigt een vrijgegeven team zijn uiterlijk, dan geldt dat binnen het team meteen, naar buiten pas na een nieuwe vrijgave.\nVrijgegeven teams staan op de pagina „Alle teams”. Hun events staan op de teampagina; in de community staan alleen de globale events van pumpfoil.org.\nZet de leiding de ranglijsten openbaar, dan ziet iedereen ze, ook zonder in te loggen, maar alleen plaats, weergavenaam, initialen en waarde. Sessies, spots, datums en profielfoto's zien alleen ingelogde gebruikers.\nZoekmachines nemen teampagina's niet op.\nDe leiding bepaalt wie de ledenlijst ziet: alleen leden of alle ingelogde gebruikers.",
    "team.regeln.oeffentlich.titel" to "Wat openbaar is",
    "team.regeln.rollen.text" to "De leiding mag alles: instellingen, ranglijsten, events, moderators aanwijzen, de leiding overdragen en het team verwijderen.\nModerators nemen verzoeken aan of wijzen ze af, verwijderen leden en maken events aan. Verder wijzigen ze niets.\nLeden zien alles in het team en kunnen op elk moment vertrekken.\nDe leiding kan pas vertrekken als ze de leiding heeft overgedragen.",
    "team.regeln.rollen.titel" to "Rollen",
    "team.regeln.statistik.text" to "Boven de ranglijsten staan de totalen van alle leden in de gekozen periode: pumps, on-foil-afstand en -tijd, sessies, runs en hoeveel leden actief waren.\nTeam tegen team: in de community vergelijken de teamranglijsten alle vrijgegeven teams met openbare ranglijsten, per kengetal met de som van de beste 3, 5 of 10 riders. Daar geldt voor alle teams dezelfde maat, niet de filters van hun eigen ranglijsten.\nWie in twee teams zit, telt voor allebei.",
    "team.regeln.statistik.titel" to "Teamtotalen",
    "team.regeln.titel" to "Teamregels",
    "team.regeln.was.text" to "Een vaste groep met eigen ranglijsten, events en een teamchat.\nIedereen kan teams oprichten, ook meerdere, en in meerdere teams zitten.\nEen nieuw team werkt meteen, via uitnodigingslinks.",
    "team.regeln.was.titel" to "Wat is een team?",
    "team.rolle.leiter" to "Leiding",
    "team.rolle.mitglied" to "Lid",
    "team.rolle.moderator" to "Moderator",
    "team.rolleUebergeben" to "Leiding overdragen",
    "team.sichtbar.angemeldete" to "Alle ingelogde gebruikers",
    "team.sichtbar.mitglieder" to "Alleen leden",
    "team.sichtbarkeit" to "Zichtbaarheid",
    "team.spotHinzu" to "Toevoegen",
    "team.spotWaehlen" to "Spot kiezen …",
    "team.spots" to "Teamspots",
    "team.spotsHinweis" to "Ranglijsten met „alleen teamspots” tellen alleen sessies op deze spots.",
    "team.stat.aktiv" to "actief",
    "team.stat.laeufe" to "Runs",
    "team.stat.pumps" to "Pumps",
    "team.stat.sessions" to "Sessies",
