    "team.annehmen" to "Přijmout",
    "team.auftritt" to "Vzhled",
    "team.auftrittHinweis" to "Takhle se tvůj tým zobrazuje. Změny platí v týmu hned, navenek až poté, co je schválíme.",
    "team.austreten" to "Opustit tým",
    "team.austretenFrage" to "Opustit „{name}“?",
    "team.automatischAkzeptieren" to "Přijímat přihlášky automaticky",
    "team.automatischAkzeptierenText" to "Jinak o každé žádosti rozhoduješ ty nebo moderátor.",
    "team.banner.entfernen" to "Odebrat banner týmu",
