    "team.event.ohneDateienKurz" to "Počítají se jen záznamy z hodinek, aplikace nebo propojeného účtu, žádné nahrané soubory.",
    "team.event.ohneVorlage" to "Bez šablony",
    "team.event.regelnTitel" to "Pravidla akce",
    "team.event.disclaimer" to "Akce pořádají samy týmy. pumpfoil.org nemá žádný vliv na akce ani na sliby v nich dané, finanční či jiné, a nepřebírá za ně žádnou odpovědnost. Právní cesta je vyloučena. Platby a všechny další dohody si pořadatelé a účastníci řeší sami, nezávisle na pumpfoil.org. Stejně tak pumpfoil.org nepřebírá žádnou odpovědnost za to, zda jsou naměřené hodnoty a data správné nebo zda nebyly zmanipulovány. Zobrazuje se to, co z nahraných dat spočítá veřejný zdrojový kód na GitHubu; žádné další záruky neexistují.",
