    "team.loeschenKnopf" to "Smazat natrvalo",
    "team.loeschenText" to "Tým hned zmizí pro všechny, i se žebříčky, akcemi a týmovým chatem. Data zatím uchováváme, aby šel omylem smazaný tým obnovit. Pro potvrzení napiš název týmu „{name}“.",
