    "team.mitgliederSichtbar" to "Kdo vidí seznam členů?",
    "team.name" to "Název týmu",
    "team.nichtGefunden" to "Tento tým neexistuje nebo není veřejný.",
    "team.nurFuerMitglieder" to "Žebříčky tohoto týmu vidí jen členové.",
    "team.oeffentlich" to "Veřejné žebříčky",
    "team.oeffentlichBadge" to "Veřejné žebříčky",
    "team.oeffentlichErstNachFreigabe" to "Platí až po schválení vzhledu.",
    "team.oeffentlichText" to "Pak žebříčky uvidí každý, i bez přihlášení: pořadí, zobrazované jméno a hodnotu. Vyjížďky, spoty a profilové fotky vidí jen přihlášení uživatelé.",
