    "team.platz2" to "2. místo",
    "team.platz3" to "3. místo",
    "team.podest.fahrer" to "Jezdci",
    "team.podest.stumm" to "Ztlumit",
    "team.podest.ton" to "Přehrát vítěznou znělku",
    "team.primaer" to "Primární tým",
    "team.primaerHinweis" to "V globálních akcích se počítáš jen za jeden tým: svůj primární, pokud na stránce akce nevybereš jiný.",
    "team.primaerSetzen" to "Nastavit jako primární tým",
    "team.profilHinweis" to "Zakládej týmy, přidávej se k nim a veď vlastní žebříčky.",
    "team.profilKnopf" to "Tým",
    "team.qr" to "QR kód",
    "team.qrLaden" to "Uložit QR kód",
    "team.qrTeilen" to "Sdílet QR kód",
    "team.regeln.beitreten.text" to "Pokud tým přijímá přihlášky, je na jeho stránce tlačítko „Přidat se“. Podle nastavení jsi hned členem, nebo rozhodne vedoucí či moderátor.\nJsou dva odkazy s pozvánkou: jeden, se kterým jsi hned členem, a druhý, kterým pošleš žádost. Oba jsou i jako QR kód.\nKdo ještě nemá účet, založí si ho a pak je rovnou v týmu, případně má žádost odeslanou.\nNově vytvořený odkaz nahradí starý, který pak přestane platit.\nKaždým vstupem souhlasíš s tím, že žebříčky týmu můžou být veřejné, i když zrovna nejsou.\nU žádosti vidí vedoucí a moderátoři, na kterých spotech a v jakých sportech jsi dosud jezdil (jen počet sessions).",
    "team.regeln.beitreten.titel" to "Přidání do týmu",
    "team.regeln.bestenlisten.text" to "Za každého se počítá jen jeden záznam: nejlepší hodnota z jedné vyjížďky, nebo u součtů všechno ve zvoleném období dohromady.\nPočítají se všechny vyjížďky členů, i ty z doby před vstupem. Kdo odejde, hned ze žebříčků zmizí.\nU akcí to platí jen do konce, viz „Akce“.\nPlatí stejné filtry jako u komunitních rekordů: smazané, nahlášené, nezařazené a probíhající nahrávky se nepočítají.\nKaždý žebříček lze omezit na jeden sport, jeden rozsah foilů, nahrávky s pohybovými daty, telefon na desce nebo týmové spoty.\nKdyž je zapnuté „Skrýt místo“, vyjížďka se nikdy nezapočítá pro konkrétní spot.\nPři shodě je výš ten, kdo hodnotu zajel dřív.",
    "team.regeln.bestenlisten.titel" to "Žebříčky",
    "team.regeln.chat.text" to "Týmový chat čtou a píšou do něj jen aktivní členové. Kdo jen poslal žádost, nevidí ho.\nPro ostatní se nikde neobjeví, ani mezi aktivními chaty.\nKdo odejde nebo je odebrán, hned ztratí přístup a nedostává už žádná upozornění.",
    "team.regeln.chat.titel" to "Týmový chat",
    "team.regeln.events.text" to "Akce má časové okno a vlastní žebříčky, volitelně jen na vybraných spotech.\nNavíc nebo místo žebříčků může akce ukazovat součty za všechny účastníky, třeba pumpy nebo vzdálenost celého týmu. Každá akce potřebuje aspoň jeden žebříček nebo jeden součet.\nPočítají se jen vyjížďky, které v časovém okně začnou.\nU každé akce může vedoucí určit, že ručně nahrané soubory (FIT, GPX, TCX) se nepočítají; záznamy z hodinek, aplikace a propojených účtů se počítají dál.\nPo konci lze ještě 4 hodiny nahrávat, stránka týmu pak ukazuje „vyhodnocování“. Potom je výsledek zmrazený a pozdější ořezání nebo smazání už nic nezmění.\nKdo odejde po konci, zůstává ve výsledku; kdo se přidá potom, už se nezapočítá.\nZmrazuje se v noci a navíc hned, jakmile někdo otevře stránku týmu.\nČasy platí v časovém pásmu, ve kterém byla akce vytvořena, a tak se zobrazují všem.\nMísta 1 až 3 dostanou odznak z akce na své stránce foilera, ale jen u týmů, jejichž vzhled je schválený.",
    "team.regeln.events.titel" to "Akce",
    "team.regeln.global.text" to "Globální eventy pořádá samo pumpfoil.org. Automaticky se počítá každý s odpovídajícími sessions v časovém okně, bez vstupu do týmu a bez přihlašování.\nKdo se nechce účastnit, vypne to v profilu v části „Soukromí“ („Neúčastnit se globálních eventů“). Pak chybí v žebříčcích, týmových hodnoceních, součtech a odznacích, i v již skončených eventech.\nKaždý žebříček má týmové pořadí: součet nejlepších členů každého týmu, obvykle 5, u rychlostí (sprintů) jejich průměr. Účastní se schválené týmy s veřejnými žebříčky. Kdo je v několika týmech, počítá se jen za jeden: za tým zvolený na stránce akce, jinak za svůj primární tým (★, nastavený na stránce týmu nebo v „Moje týmy“). Bez vlastní volby zůstane při vstupu do dalšího týmu primárním ten dosavadní – nový nebo zvětšený tým nikdy nepřevezme sám. Vlastní týmy, které se nepočítají (neschválené nebo s neveřejnými žebříčky), jsou na stránce akce zobrazené šedě. Změnit to lze do 6 hodin před koncem akce.\nŽebříčky jsou vidět i bez přihlášení přes odkaz na event: pořadí, zobrazované jméno, iniciály a hodnota.\nJinak platí pravidla pro eventy: časové okno, vyhodnocení, zmrazení a odznaky za místa 1 až 3, na profilové stránce označené „Global“.",
    "team.regeln.global.titel" to "Globální eventy",
    "team.regeln.intro" to "Jak fungují týmy na pumpfoil.org: kdo co vidí, jak se hodnotí a co se stane při smazání.",
    "team.regeln.konto.text" to "Člověk zmizí ze všech týmů a žebříčků a také ze zmrazených výsledků akcí. Ti pod ním se posunou nahoru.\nPokud vedl tým, převezme ho nejdéle sloužící moderátor, jinak nejdéle sloužící člen. Pokud už nikdo nezbyl, tým se smaže.",
    "team.regeln.konto.titel" to "Když se smaže účet",
    "team.regeln.link" to "Pravidla týmů",
    "team.regeln.loeschen.text" to "Smazat tým může jen vedoucí, a jen když pro potvrzení napíše název týmu.\nTým pak zmizí pro všechny: členství, žebříčky, deník, akce i týmový chat. Data zatím uchováváme, aby šel omylem smazaný tým obnovit.\nAdresa týmu zůstane zablokovaná a nikdy se nepřidělí jinému týmu.",
    "team.regeln.loeschen.titel" to "Smazání týmu",
    "team.regeln.logbuch.text" to "Deník zaznamenává, kdo kdy překonal který týmový rekord. Aktualizuje se každou noc.\nPrvní záznam žebříčku je stav v první noci po jeho založení.\nU nejlepších hodnot se počítá každé zlepšení, i vlastní. U součtů se počítá jen to, když se někdo dostane do čela.\nKdyž rekord klesne, protože byla smazána vyjížďka nebo někdo odešel, upraví se to potichu, bez záznamu.",
    "team.regeln.logbuch.titel" to "Deník",
    "team.regeln.oeffentlich.text" to "Uvnitř smí tým všechno. Navenek se objeví, až když jsme si jednou prohlédli a schválili jeho název, adresu, popis, znak a barvu.\nBanner týmu prochází stejným schválením jako znak. Kterou část je vidět, volí vedoucí bez nového schválení; když banner odebere, zmizí hned i z veřejné stránky.\nKdyž schválený tým změní svůj vzhled, v týmu to platí hned, navenek až po novém schválení.\nSchválené týmy jsou na stránce „Všechny týmy“. Jejich eventy jsou na stránce týmu; v komunitě jsou jen globální eventy pumpfoil.org.\nKdyž vedoucí zveřejní žebříčky, vidí je každý, i bez přihlášení, ale jen pořadí, zobrazované jméno, iniciály a hodnotu. Vyjížďky, spoty, data a profilové fotky vidí jen přihlášení uživatelé.\nVyhledávače stránky týmů neindexují.\nKdo vidí seznam členů, určuje vedoucí: jen členové, nebo všichni přihlášení.",
    "team.regeln.oeffentlich.titel" to "Co je veřejné",
    "team.regeln.rollen.text" to "Vedoucí smí všechno: nastavení, žebříčky, akce, jmenování moderátorů, předání vedení a smazání týmu.\nModerátoři přijímají nebo odmítají žádosti, odebírají členy a zakládají akce. Nic jiného nemění.\nČlenové vidí v týmu všechno a můžou kdykoli odejít.\nVedoucí může odejít, až když předá vedení.",
    "team.regeln.rollen.titel" to "Role",
    "team.regeln.statistik.text" to "Nad žebříčky jsou součty všech členů ve zvoleném období: pumpnutí, vzdálenost a čas na foilu, vyjížďky, jízdy a kolik členů bylo aktivních.\nTým proti týmu: v komunitě týmové žebříčky porovnávají všechny schválené týmy s veřejnými žebříčky, u každé metriky součtem nejlepších 3, 5 nebo 10 jezdců. Platí tam pro všechny týmy stejné měřítko, ne filtry jejich vlastních žebříčků.\nKdo je ve dvou týmech, počítá se pro oba.",
    "team.regeln.statistik.titel" to "Týmové součty",
    "team.regeln.titel" to "Pravidla týmů",
    "team.regeln.was.text" to "Pevná skupina s vlastními žebříčky, akcemi a týmovým chatem.\nKaždý může zakládat týmy, i víc najednou, a být ve více týmech.\nNový tým funguje hned, přes odkazy s pozvánkou.",
    "team.regeln.was.titel" to "Co je tým?",
    "team.rolle.leiter" to "Vedoucí",
