    "team.links" to "Linki z zaproszeniem",
    "team.linksHinweis" to "Dwa linki do rozesłania. Kto nie ma jeszcze konta, zakłada je i od razu jest w drużynie.",
    "team.loeschen" to "Usuń drużynę",
    "team.loeschenKnopf" to "Usuń trwale",
    "team.loeschenText" to "Drużyna od razu znika dla wszystkich, razem z rankingami, wydarzeniami i czatem. Na razie przechowujemy dane, aby dało się przywrócić drużynę usuniętą przez pomyłkę. Aby potwierdzić, wpisz nazwę drużyny „{name}”.",
    "team.logbuch" to "Dziennik",
