    "team.mitgliederSichtbar" to "Kto widzi listę członków?",
    "team.name" to "Nazwa drużyny",
    "team.nichtGefunden" to "Ta drużyna nie istnieje albo nie jest publiczna.",
    "team.nurFuerMitglieder" to "Rankingi tej drużyny widzą tylko członkowie.",
    "team.oeffentlich" to "Publiczne rankingi",
    "team.oeffentlichBadge" to "Publiczne rankingi",
    "team.oeffentlichErstNachFreigabe" to "Działa dopiero po zatwierdzeniu wyglądu.",
    "team.oeffentlichText" to "Wtedy każdy widzi rankingi, także bez logowania: miejsce, nazwę wyświetlaną i wartość. Sesje, spoty i zdjęcia profilowe widzą tylko zalogowani.",
    "team.platz1" to "1. miejsce",
    "team.platz2" to "2. miejsce",
    "team.platz3" to "3. miejsce",
    "team.podest.fahrer" to "Zawodnicy",
    "team.podest.stumm" to "Wycisz",
    "team.podest.ton" to "Odtwórz dźwięk zwycięzcy",
    "team.primaer" to "Główna drużyna",
    "team.primaerHinweis" to "W wydarzeniach globalnych liczysz się tylko dla jednej drużyny: głównej, chyba że na stronie wydarzenia wybierzesz inną.",
    "team.primaerSetzen" to "Ustaw jako główną drużynę",
    "team.profilHinweis" to "Zakładaj drużyny, dołączaj do nich i prowadź własne rankingi.",
    "team.profilKnopf" to "Drużyna",
    "team.qr" to "Kod QR",
    "team.qrLaden" to "Zapisz kod QR",
    "team.qrTeilen" to "Udostępnij kod QR",
    "team.regeln.beitreten.text" to "Jeśli drużyna przyjmuje zgłoszenia, na jej stronie jest przycisk „Dołącz”. Zależnie od ustawienia od razu jesteś członkiem albo decyduje lider lub moderator.\nSą dwa linki z zaproszeniem: jeden, z którym od razu zostajesz członkiem, i drugi, który wysyła prośbę. Oba są też dostępne jako kod QR.\nKto nie ma jeszcze konta, zakłada je i od razu jest w drużynie albo ma już wysłaną prośbę.\nNowo utworzony link zastępuje stary, który wtedy przestaje działać.\nPrzy każdym dołączeniu zgadzasz się, że rankingi drużyny mogą być publiczne, nawet jeśli teraz nie są.\nPrzy prośbie lider i moderatorzy widzą, na jakich spotach i w jakich sportach do tej pory pływałeś (tylko liczbę sesji).",
    "team.regeln.beitreten.titel" to "Dołączanie",
    "team.regeln.bestenlisten.text" to "Każda osoba liczy się tylko raz: jej najlepsza wartość z jednej sesji, a przy sumach wszystko z wybranego okresu razem.\nLiczą się wszystkie sesje członków, także te sprzed dołączenia. Kto opuści drużynę, od razu znika z list.\nW wydarzeniach dotyczy to tylko czasu do końca, zob. „Wydarzenia”.\nObowiązują te same filtry co przy rekordach społeczności: usunięte, zgłoszone, nieprzypisane i trwające nagrania się nie liczą.\nKażdy ranking można ograniczyć do jednego sportu, jednego zakresu foili, nagrań z danymi ruchu, telefonu na desce albo spotów drużyny.\nJeśli włączone jest „Ukryj miejsce”, sesja nigdy nie liczy się dla konkretnego spotu.\nPrzy remisie wyżej jest ten, kto osiągnął wynik pierwszy.",
    "team.regeln.bestenlisten.titel" to "Rankingi",
    "team.regeln.chat.text" to "Czat drużyny czytają i piszą w nim tylko aktywni członkowie. Kto tylko wysłał prośbę, nie widzi go.\nDla innych nie pojawia się nigdzie, także wśród aktywnych czatów.\nKto opuści drużynę albo zostanie usunięty, od razu traci dostęp i nie dostaje już powiadomień.",
    "team.regeln.chat.titel" to "Czat drużyny",
    "team.regeln.events.text" to "Wydarzenie ma okno czasowe i własne rankingi, w razie potrzeby tylko na wybranych spotach.\nOprócz rankingów lub zamiast nich wydarzenie może pokazywać sumy wszystkich uczestników, np. pumpy lub dystans całej drużyny. Każde wydarzenie potrzebuje co najmniej jednego rankingu lub jednej sumy.\nLiczą się tylko sesje rozpoczęte w tym oknie czasowym.\nDla każdego wydarzenia lider może ustalić, że ręcznie przesłane pliki (FIT, GPX, TCX) się nie liczą; nagrania z zegarków, aplikacji i połączonych kont nadal się liczą.\nPo zakończeniu można jeszcze przez 4 godziny wgrywać sesje, strona drużyny pokazuje wtedy „liczenie wyników”. Potem wynik zostaje zamrożony i późniejsze przycinanie czy usuwanie niczego już nie zmienia.\nKto odejdzie po zakończeniu, zostaje w wyniku; kto dołączy później, nie zostanie już dodany.\nWyniki są zamrażane w nocy, a dodatkowo, gdy tylko ktoś otworzy stronę drużyny.\nGodziny obowiązują w strefie czasowej, w której utworzono wydarzenie, i wszyscy widzą je właśnie tak.\nMiejsca od 1 do 3 dostają odznakę z wydarzenia na swojej stronie foilera, ale tylko w drużynach, których wygląd jest zatwierdzony.",
    "team.regeln.events.titel" to "Wydarzenia",
    "team.regeln.global.text" to "Globalne eventy organizuje samo pumpfoil.org. Automatycznie liczy się każdy z pasującymi sesjami w okresie eventu, bez dołączania i bez zapisów.\nKto nie chce brać udziału, wyłącza to w profilu w „Prywatność” („Nie bierz udziału w globalnych eventach”). Wtedy znika z rankingów, klasyfikacji drużyn, sum i odznak, także w eventach, które już się skończyły.\nKażda tabela ma ranking drużyn: suma najlepszych członków każdej drużyny, zwykle 5, a przy prędkościach (sprintach) ich średnia. Biorą w nim udział zatwierdzone drużyny z publicznymi tabelami. Kto należy do kilku drużyn, liczy się tylko dla jednej: wybranej na stronie wydarzenia, a w przeciwnym razie swojej głównej (★, ustawionej na stronie drużyny lub w „Moje drużyny”). Bez własnego wyboru przy dołączeniu do kolejnej drużyny główną pozostaje dotychczasowa – nowa lub większa drużyna nigdy nie przejmuje tego sama. Własne drużyny, które się nie liczą (niezatwierdzone lub z niepublicznymi tabelami), są na stronie wydarzenia wyszarzone. Można to zmienić do 6 godzin przed końcem wydarzenia.\nRankingi są widoczne także bez logowania przez link do eventu: miejsce, nazwa wyświetlana, inicjały i wartość.\nPoza tym obowiązują zasady eventów: okres, ocena, zamrożenie i odznaki za miejsca 1–3, oznaczone na stronie profilu jako „Global”.",
    "team.regeln.global.titel" to "Globalne eventy",
    "team.regeln.intro" to "Jak działają drużyny na pumpfoil.org: kto co widzi, jak liczone są wyniki i co się dzieje przy usuwaniu.",
    "team.regeln.konto.text" to "Osoba znika ze wszystkich drużyn i rankingów, a także z zamrożonych wyników wydarzeń. Osoby poniżej przesuwają się w górę.\nJeśli prowadziła drużynę, przejmuje ją najdłużej działający moderator, a jeśli go nie ma, najdłużej należący członek. Jeśli nikt nie zostanie, drużyna jest usuwana.",
    "team.regeln.konto.titel" to "Gdy konto zostaje usunięte",
    "team.regeln.link" to "Zasady drużyny",
    "team.regeln.loeschen.text" to "Drużynę może usunąć tylko lider i tylko po wpisaniu nazwy drużyny dla potwierdzenia.\nWtedy drużyna znika dla wszystkich: członkostwa, rankingi, dziennik, wydarzenia i czat drużyny. Na razie przechowujemy dane, aby dało się przywrócić drużynę usuniętą przez pomyłkę.\nAdres drużyny pozostaje zablokowany i nigdy nie zostanie przydzielony innej drużynie.",
    "team.regeln.loeschen.titel" to "Usuwanie drużyny",
    "team.regeln.logbuch.text" to "Dziennik zapisuje, kto i kiedy pobił który rekord drużyny. Jest aktualizowany co noc.\nPierwszy wpis rankingu to stan z pierwszej nocy po jego utworzeniu.\nPrzy najlepszych wartościach liczy się każda poprawa, także własna. Przy sumach liczy się tylko objęcie prowadzenia.\nJeśli rekord spada, bo usunięto sesję albo ktoś opuścił drużynę, jest to po cichu korygowane, bez wpisu.",
    "team.regeln.logbuch.titel" to "Dziennik",
    "team.regeln.oeffentlich.text" to "Wewnątrz drużyna może wszystko. Na zewnątrz pojawia się dopiero wtedy, gdy obejrzymy i zatwierdzimy jej nazwę, adres, opis, herb i kolor.\nBaner drużyny przechodzi tę samą akceptację co herb. Którą część widać, wybiera lider bez nowej akceptacji; jeśli usunie baner, znika on od razu także ze strony publicznej.\nJeśli zatwierdzona drużyna zmieni swój wygląd, w drużynie obowiązuje to od razu, a na zewnątrz dopiero po ponownym zatwierdzeniu.\nZatwierdzone drużyny są na stronie „Wszystkie drużyny”. Ich eventy są na stronie drużyny; w społeczności są tylko globalne eventy pumpfoil.org.\nJeśli lider ustawi rankingi jako publiczne, widzi je każdy, także bez logowania, ale tylko miejsce, nazwę wyświetlaną, inicjały i wartość. Sesje, spoty, daty i zdjęcia profilowe widzą tylko zalogowani.\nWyszukiwarki nie indeksują stron drużyn.\nLider decyduje, kto widzi listę członków: tylko członkowie czy wszyscy zalogowani.",
    "team.regeln.oeffentlich.titel" to "Co jest publiczne",
    "team.regeln.rollen.text" to "Lider może wszystko: ustawienia, rankingi, wydarzenia, wyznaczanie moderatorów, przekazanie roli lidera i usunięcie drużyny.\nModeratorzy przyjmują lub odrzucają prośby, usuwają członków i tworzą wydarzenia. Niczego więcej nie zmieniają.\nCzłonkowie widzą wszystko w drużynie i mogą ją opuścić w każdej chwili.\nLider może opuścić drużynę dopiero po przekazaniu roli lidera.",
    "team.regeln.rollen.titel" to "Role",
    "team.regeln.statistik.text" to "Nad rankingami widać sumy wszystkich członków w wybranym okresie: pompy, dystans i czas na foilu, sesje, przejazdy oraz liczbę aktywnych członków.\nDrużyna kontra drużyna: w społeczności rankingi drużyn porównują wszystkie zatwierdzone drużyny z publicznymi rankingami, w każdej kategorii sumą najlepszych 3, 5 lub 10 riderów. Obowiązuje tam ta sama miara dla wszystkich drużyn, nie filtry ich własnych rankingów.\nKto jest w dwóch drużynach, liczy się dla obu.",
    "team.regeln.statistik.titel" to "Sumy drużyny",
    "team.regeln.titel" to "Zasady drużyny",
    "team.regeln.was.text" to "Stała grupa z własnymi rankingami, wydarzeniami i czatem drużyny.\nKażdy może zakładać drużyny, także kilka, i należeć do kilku drużyn.\nNowa drużyna działa od razu, przez linki z zaproszeniem.",
    "team.regeln.was.titel" to "Czym jest drużyna?",
