    "team.podest.fahrer" to "Atletas",
    "team.podest.stumm" to "Mudo",
    "team.podest.ton" to "Tocar som do vencedor",
    "team.primaer" to "Equipe principal",
    "team.primaerHinweis" to "Nos eventos globais você conta para uma equipe só: a sua equipe principal, a menos que escolha outra na página do evento.",
    "team.primaerSetzen" to "Definir como equipe principal",
    "team.profilHinweis" to "Crie equipes ou participe delas, com rankings próprios.",
    "team.profilKnopf" to "Equipe",
    "team.qr" to "QR code",
    "team.qrLaden" to "Salvar QR code",
    "team.qrTeilen" to "Compartilhar QR code",
    "team.regeln.beitreten.text" to "Se uma equipe permite inscrições, a página dela mostra um botão “Participar”. Dependendo da configuração, você vira membro na hora, ou o líder ou um moderador decide.\nExistem dois links de convite: um com o qual você vira membro na hora e outro com o qual você envia um pedido. Os dois também existem como QR code.\nQuem ainda não tem conta cria uma e depois já está na equipe ou já enviou o pedido.\nUm link novo substitui o antigo, que deixa de funcionar.\nA cada entrada, você concorda que os rankings da equipe podem ser públicos, mesmo que não sejam agora.\nNum pedido, o líder e os moderadores veem em quais spots e esportes você já andou até agora (só o número de sessões).",
    "team.regeln.beitreten.titel" to "Entrar",
    "team.regeln.bestenlisten.text" to "Cada pessoa conta uma vez só: o melhor valor de uma sessão ou, nos totais, tudo do período escolhido somado.\nContam todas as sessões dos membros, inclusive as de antes de entrar. Quem sai some dos rankings na hora.\nNos eventos isso só vale até o fim, veja “Eventos”.\nValem os mesmos filtros dos recordes da comunidade: gravações excluídas, denunciadas, sem atribuição e em andamento não contam.\nCada ranking pode ser limitado a um esporte, uma faixa de foils, gravações com dados de movimento, telefone na prancha ou os spots da equipe.\nSe “Ocultar o local” estiver ativado, a sessão nunca conta para um spot específico.\nEm caso de empate, fica na frente quem fez o valor primeiro.",
    "team.regeln.bestenlisten.titel" to "Rankings",
    "team.regeln.chat.text" to "Só membros ativos leem e escrevem no chat da equipe. Quem só enviou um pedido não o vê.\nEle não aparece em lugar nenhum para os outros, nem entre os chats ativos.\nQuem sai ou é removido perde o acesso na hora e não recebe mais notificações.",
    "team.regeln.chat.titel" to "Chat da equipe",
    "team.regeln.events.text" to "Um evento tem um período e rankings próprios, se quiser só em certos spots.\nAlém dos rankings, ou no lugar deles, um evento pode mostrar totais de todos os participantes, como os pumps ou a distância da equipe inteira. Todo evento precisa de pelo menos um ranking ou um total.\nSó contam as sessões que começam dentro do período.\nEm cada evento o líder pode definir que arquivos enviados à mão (FIT, GPX, TCX) não contam; gravações de relógios, do app e de contas vinculadas continuam contando.\nDepois do fim ainda dá para enviar por 4 horas; a página da equipe mostra então “apurando”. Depois disso o resultado fica congelado, e cortar ou excluir depois não muda mais nada.\nQuem sair depois do fim continua no resultado; quem entrar depois não é mais incluído.\nOs resultados são congelados à noite e também assim que alguém abre a página da equipe.\nOs horários valem no fuso horário em que o evento foi criado e aparecem assim para todo mundo.\nOs lugares 1 a 3 ganham uma medalha do evento na página de foiler, mas só em equipes com aparência aprovada.",
    "team.regeln.events.titel" to "Eventos",
    "team.regeln.global.text" to "Os eventos globais são organizados pelo próprio pumpfoil.org. Conta automaticamente quem tem sessões adequadas no período, sem entrar em equipe e sem se inscrever.\nQuem não quiser participar desliga isso no perfil em “Privacidade” (“Não participar de eventos globais”). Aí some dos rankings, classificações de equipe, totais e selos, inclusive em eventos já encerrados.\nCada ranking tem uma classificação por equipes: a soma dos melhores membros de cada equipe, normalmente 5, e nas velocidades (sprints) a média deles. Participam equipes aprovadas com rankings públicos. Quem está em várias equipes conta só para uma: a escolhida na página do evento, senão a equipe principal (★, definida na página da equipe ou em “Minhas equipes”). Sem escolha própria, ao entrar em outra equipe a equipe atual continua sendo a principal – uma equipe nova ou que cresceu nunca assume sozinha. Suas equipes que não contam (não aprovadas ou com rankings não públicos) aparecem em cinza na página do evento. Dá para mudar até 6 horas antes do fim do evento.\nOs rankings também ficam visíveis sem login pelo link do evento: posição, nome de exibição, iniciais e valor.\nNo mais, valem as regras de eventos: período, apuração, congelamento e selos para as posições 1 a 3, marcados com “Global” na página de perfil.",
    "team.regeln.global.titel" to "Eventos globais",
    "team.regeln.intro" to "Como as equipes funcionam no pumpfoil.org: quem vê o quê, como a pontuação funciona e o que acontece quando algo é excluído.",
    "team.regeln.konto.text" to "A pessoa some de todas as equipes e rankings, e também dos resultados congelados de eventos. Quem está abaixo sobe.\nSe ela liderava uma equipe, assume o moderador mais antigo, senão o membro mais antigo. Se não sobrar ninguém, a equipe é excluída.",
    "team.regeln.konto.titel" to "Quando uma conta é excluída",
    "team.regeln.link" to "Regras das equipes",
    "team.regeln.loeschen.text" to "Só o líder pode excluir uma equipe, e só digitando o nome da equipe para confirmar.\nAí a equipe some para todos: participações, classificações, diário de bordo, eventos e o chat da equipe. Por enquanto guardamos os dados para poder restaurar uma equipe excluída por engano.\nO endereço da equipe fica bloqueado e nunca é passado para outra equipe.",
    "team.regeln.loeschen.titel" to "Excluir uma equipe",
    "team.regeln.logbuch.text" to "O diário de bordo registra quem bateu qual recorde da equipe, e quando. Ele é atualizado toda noite.\nA primeira entrada de um ranking é a situação na primeira noite depois de ele ser criado.\nNos melhores valores, toda melhora conta, inclusive a própria. Nos totais, só conta quando alguém assume a liderança.\nSe um recorde cai porque uma sessão foi excluída ou alguém saiu, ele é ajustado em silêncio, sem entrada.",
    "team.regeln.logbuch.titel" to "Diário de bordo",
    "team.regeln.oeffentlich.text" to "Internamente, uma equipe pode fazer tudo. Para fora, ela só aparece depois que olhamos e aprovamos nome, endereço, descrição, emblema e cor.\nO banner da equipe passa pela mesma aprovação que o emblema. Qual parte aparece é a liderança que escolhe, sem nova aprovação; se ela remover o banner, ele some na hora também da página pública.\nSe uma equipe aprovada muda a aparência, isso vale na equipe na hora e para o público depois de uma nova aprovação.\nEquipes aprovadas aparecem na página “Todas as equipes”. Os eventos delas ficam na página da equipe; na comunidade aparecem só os eventos globais do pumpfoil.org.\nSe o líder deixa os rankings públicos, qualquer pessoa os vê, mesmo sem entrar, mas só posição, nome de exibição, iniciais e valor. Sessões, spots, datas e fotos de perfil só são visíveis para usuários conectados.\nBuscadores não indexam páginas de equipes.\nO líder decide quem vê a lista de membros: só os membros ou todos os usuários conectados.",
    "team.regeln.oeffentlich.titel" to "O que é público",
    "team.regeln.rollen.text" to "O líder pode fazer tudo: configurações, rankings, eventos, nomear moderadores, passar a liderança e excluir a equipe.\nOs moderadores aceitam ou recusam pedidos, removem membros e criam eventos. Não mudam mais nada.\nOs membros veem tudo na equipe e podem sair a qualquer momento.\nO líder só pode sair depois de passar a liderança.",
    "team.regeln.rollen.titel" to "Funções",
    "team.regeln.statistik.text" to "Acima dos rankings ficam os totais de todos os membros no período escolhido: pumps, distância e tempo on-foil, sessões, voltas e quantos membros estiveram ativos.\nEquipe contra equipe: na comunidade, os rankings de equipes comparam todas as equipes aprovadas com rankings públicos, em cada métrica pela soma dos 3, 5 ou 10 melhores riders. Ali vale a mesma medida para todas as equipes, não os filtros dos próprios rankings.\nQuem está em duas equipes conta para as duas.",
    "team.regeln.statistik.titel" to "Totais da equipe",
    "team.regeln.titel" to "Regras das equipes",
    "team.regeln.was.text" to "Um grupo fixo com rankings próprios, eventos e um chat da equipe.\nQualquer pessoa pode criar equipes, até várias, e participar de várias equipes.\nUma equipe nova funciona na hora, por links de convite.",
