    "team.logbuch" to "Diário de bordo",
    "team.logbuch.gebrochen" to "{name} bate «{was}» com {wert} (antes: {vorher}, {vorherWert})",
    "team.logbuch.start" to "{name} detém «{was}» com {wert}",
    "team.logbuchHinweis" to "Quem bateu qual recorde da equipa, e quando. Atualizado todas as noites.",
    "team.logbuchLeer" to "Ainda sem registos. A primeira classificação aparece na noite a seguir à criação dos rankings.",
    "team.logoHochladen" to "Enviar emblema",
    "team.meine" to "As minhas equipas",
    "team.mitglieder" to "Membros",
    "team.mitgliederAnzahl" to "{n} membros",
    "team.mitgliederSichtbar" to "Quem vê a lista de membros?",
    "team.name" to "Nome da equipa",
    "team.nichtGefunden" to "Esta equipa não existe ou não é pública.",
    "team.nurFuerMitglieder" to "Só os membros veem os rankings desta equipa.",
    "team.oeffentlich" to "Rankings públicos",
    "team.oeffentlichBadge" to "Rankings públicos",
    "team.oeffentlichErstNachFreigabe" to "Só tem efeito depois de a aparência ser aprovada.",
    "team.oeffentlichText" to "Assim qualquer pessoa vê os rankings, mesmo sem iniciar sessão: posição, nome de exibição e valor. Sessões, spots e fotos de perfil continuam visíveis só para utilizadores com sessão iniciada.",
    "team.platz1" to "1.º lugar",
    "team.platz2" to "2.º lugar",
    "team.platz3" to "3.º lugar",
    "team.podest.fahrer" to "Atletas",
    "team.podest.stumm" to "Silenciar",
    "team.podest.ton" to "Tocar som do vencedor",
    "team.primaer" to "Equipa principal",
    "team.primaerHinweis" to "Nos eventos globais contas para uma só equipa: a tua equipa principal, a não ser que escolhas outra na página do evento.",
    "team.primaerSetzen" to "Definir como equipa principal",
    "team.profilHinweis" to "Cria equipas ou junta-te a elas, com rankings próprios.",
    "team.profilKnopf" to "Equipa",
    "team.qr" to "Código QR",
    "team.qrLaden" to "Guardar código QR",
    "team.qrTeilen" to "Partilhar código QR",
    "team.regeln.beitreten.text" to "Se uma equipa permite inscrições, a sua página mostra um botão «Aderir». Conforme a definição, passas logo a membro, ou decide o líder ou um moderador.\nHá dois links de convite: um com o qual passas logo a membro e outro com o qual envias um pedido. Ambos existem também como código QR.\nQuem ainda não tem conta cria uma e fica depois logo na equipa ou já enviou o pedido.\nUm link novo substitui o antigo, que deixa de funcionar.\nSempre que aderes, aceitas que os rankings da equipa possam ser públicos, mesmo que agora não o sejam.\nNum pedido, o líder e os moderadores veem em que spots e desportos já andaste até agora (só o número de sessões).",
    "team.regeln.beitreten.titel" to "Aderir",
    "team.regeln.bestenlisten.text" to "Cada pessoa conta só uma vez: o seu melhor valor numa sessão ou, nos totais, tudo o que fez no período escolhido somado.\nContam todas as sessões dos membros, incluindo as de antes da adesão. Quem sai desaparece logo das listas.\nNos eventos isto só vale até ao fim, ver «Eventos».\nAplicam-se os mesmos filtros dos recordes da comunidade: gravações eliminadas, denunciadas, não atribuídas e em curso não contam.\nCada ranking pode ser limitado a um desporto, uma faixa de foils, gravações com dados de movimento, telefone na prancha ou os spots da equipa.\nSe «Esconder o local» estiver ativo, a sessão nunca conta para um spot específico.\nEm caso de empate, fica à frente quem fez o valor primeiro.",
    "team.regeln.bestenlisten.titel" to "Rankings",
    "team.regeln.chat.text" to "Só os membros ativos leem e escrevem no chat da equipa. Quem só enviou um pedido não o vê.\nNão aparece em lado nenhum para os outros, nem sequer entre os chats ativos.\nQuem sai ou é removido perde logo o acesso e deixa de receber notificações.",
    "team.regeln.chat.titel" to "Chat da equipa",
    "team.regeln.events.text" to "Um evento tem um período e rankings próprios, se quiseres só em certos spots.\nAlém dos rankings, ou em vez deles, um evento pode mostrar totais de todos os participantes, como os pumps ou a distância da equipa inteira. Cada evento precisa de pelo menos um ranking ou um total.\nSó contam as sessões que começam dentro do período.\nEm cada evento o líder pode definir que ficheiros carregados à mão (FIT, GPX, TCX) não contam; gravações de relógios, da app e de contas ligadas continuam a contar.\nDepois do fim ainda é possível enviar durante 4 horas; a página da equipa mostra então «a apurar». A partir daí o resultado fica congelado, e cortar ou eliminar mais tarde já não muda nada.\nQuem sair depois do fim continua no resultado; quem aderir depois já não é incluído.\nOs resultados são congelados à noite e também assim que alguém abre a página da equipa.\nAs horas valem no fuso horário em que o evento foi criado e são mostradas assim a todos.\nOs lugares 1 a 3 recebem uma medalha do evento na sua página de foiler, mas só em equipas cuja aparência está aprovada.",
    "team.regeln.events.titel" to "Eventos",
    "team.regeln.global.text" to "Os eventos globais são organizados pelo próprio pumpfoil.org. Conta automaticamente quem tem sessões adequadas no período, sem aderir a uma equipa e sem se inscrever.\nQuem não quiser participar desliga isso no perfil em «Privacidade» («Não participar em eventos globais»). Nesse caso desaparece das classificações, classificações de equipa, totais e emblemas, também em eventos já terminados.\nCada classificação tem uma classificação por equipas: a soma dos melhores membros de cada equipa, normalmente 5, e nas velocidades (sprints) a média deles. Participam equipas aprovadas com classificações públicas. Quem está em várias equipas conta só para uma: a escolhida na página do evento, caso contrário a equipa principal (★, definida na página da equipa ou em “As minhas equipas”). Sem escolha própria, ao entrar noutra equipa a equipa atual continua a ser a principal – uma equipa nova ou que cresceu nunca assume o lugar sozinha. As tuas equipas que não contam (não aprovadas ou com classificações não públicas) aparecem a cinzento na página do evento. Pode ser alterado até 6 horas antes do fim do evento.\nAs classificações também são visíveis sem iniciar sessão através da ligação do evento: posição, nome de apresentação, iniciais e valor.\nDe resto aplicam-se as regras dos eventos: período, apuramento, congelamento e emblemas para as posições 1 a 3, marcados com «Global» na página de perfil.",
    "team.regeln.global.titel" to "Eventos globais",
    "team.regeln.intro" to "Como funcionam as equipas no pumpfoil.org: quem vê o quê, como se pontua e o que acontece quando algo é eliminado.",
    "team.regeln.konto.text" to "A pessoa desaparece de todas as equipas e rankings, e também dos resultados congelados de eventos. Quem está abaixo sobe.\nSe liderava uma equipa, assume o moderador mais antigo, caso contrário o membro mais antigo. Se não restar ninguém, a equipa é eliminada.",
    "team.regeln.konto.titel" to "Quando uma conta é eliminada",
    "team.regeln.link" to "Regras das equipas",
    "team.regeln.loeschen.text" to "Só o líder pode eliminar uma equipa, e só escrevendo o nome da equipa para confirmar.\nA equipa desaparece então para todos: inscrições, classificações, diário de bordo, eventos e o chat da equipa. Por agora guardamos os dados para se poder restaurar uma equipa apagada por engano.\nO endereço da equipa fica bloqueado e nunca é atribuído a outra equipa.",
    "team.regeln.loeschen.titel" to "Eliminar uma equipa",
    "team.regeln.logbuch.text" to "O diário de bordo regista quem bateu qual recorde da equipa, e quando. É atualizado todas as noites.\nA primeira entrada de um ranking é a situação na primeira noite depois de ter sido criado.\nNos melhores valores conta cada melhoria, incluindo a própria. Nos totais só conta quando alguém passa para a frente.\nSe um recorde desce porque uma sessão foi eliminada ou alguém saiu, é ajustado discretamente, sem entrada.",
    "team.regeln.logbuch.titel" to "Diário de bordo",
    "team.regeln.oeffentlich.text" to "Internamente, uma equipa pode fazer tudo. Para fora, só aparece depois de vermos e aprovarmos o nome, o endereço, a descrição, o emblema e a cor.\nO banner da equipa passa pela mesma aprovação que o emblema. Que parte se vê escolhe a liderança, sem nova aprovação; se o remover, desaparece de imediato também da página pública.\nSe uma equipa aprovada altera a sua aparência, isso vale logo dentro da equipa e para o público só depois de uma nova aprovação.\nAs equipas aprovadas aparecem na página «Todas as equipas». Os seus eventos estão na página da equipa; na comunidade só aparecem os eventos globais do pumpfoil.org.\nSe o líder torna os rankings públicos, qualquer pessoa os vê, mesmo sem iniciar sessão, mas só a posição, o nome de exibição, as iniciais e o valor. Sessões, spots, datas e fotos de perfil só são visíveis para utilizadores com sessão iniciada.\nOs motores de busca não indexam as páginas das equipas.\nO líder decide quem vê a lista de membros: só os membros ou todos os utilizadores com sessão iniciada.",
    "team.regeln.oeffentlich.titel" to "O que é público",
    "team.regeln.rollen.text" to "O líder pode fazer tudo: definições, rankings, eventos, nomear moderadores, passar a liderança e eliminar a equipa.\nOs moderadores aceitam ou recusam pedidos, removem membros e criam eventos. Não alteram mais nada.\nOs membros veem tudo na equipa e podem sair a qualquer momento.\nO líder só pode sair depois de passar a liderança.",
    "team.regeln.rollen.titel" to "Funções",
    "team.regeln.statistik.text" to "Por cima dos rankings estão os totais de todos os membros no período escolhido: pumps, distância e tempo on-foil, sessões, voltas e quantos membros estiveram ativos.\nEquipa contra equipa: na comunidade, as classificações de equipas comparam todas as equipas aprovadas com classificações públicas, em cada métrica pela soma dos 3, 5 ou 10 melhores riders. Aí aplica-se a mesma medida a todas as equipas, não os filtros das suas próprias classificações.\nQuem está em duas equipas conta para as duas.",
    "team.regeln.statistik.titel" to "Totais da equipa",
    "team.regeln.titel" to "Regras das equipas",
    "team.regeln.was.text" to "Um grupo fixo com rankings próprios, eventos e um chat da equipa.\nQualquer pessoa pode criar equipas, mesmo várias, e fazer parte de várias equipas.\nUma equipa nova funciona logo, através de links de convite.",
    "team.regeln.was.titel" to "O que é uma equipa?",
    "team.rolle.leiter" to "Líder",
    "team.rolle.mitglied" to "Membro",
    "team.rolle.moderator" to "Moderador",
    "team.rolleUebergeben" to "Passar a liderança",
    "team.sichtbar.angemeldete" to "Todos os utilizadores com sessão iniciada",
    "team.sichtbar.mitglieder" to "Só membros",
