    "team.spotHinzu" to "Adicionar",
    "team.spotWaehlen" to "Escolher spot …",
    "team.spots" to "Spots da equipa",
    "team.spotsHinweis" to "Os rankings com «só spots da equipa» contam só sessões nestes spots.",
    "team.stat.aktiv" to "ativos",
    "team.stat.laeufe" to "Voltas",
    "team.stat.pumps" to "Pumps",
