    "team.event.ohneDateien" to "ウォッチ、アプリ、連携アカウントの記録のみを集計（手動でアップロードした FIT・GPX・TCX ファイルは除外）",
    "team.event.ohneDateienKurz" to "ウォッチ、アプリ、連携アカウントの記録のみ集計され、アップロードしたファイルは含まれません。",
    "team.event.ohneVorlage" to "テンプレートなし",
    "team.event.regelnTitel" to "イベントのルール",
    "team.event.disclaimer" to "イベントは各チームが自ら主催します。pumpfoil.org はイベントや、その中でなされる金銭的その他の約束に一切関与せず、責任を負いません。法的手段による請求はできません。支払いやその他の取り決めは、pumpfoil.org とは無関係に主催者と参加者の間で行ってください。 同様に、pumpfoil.org は計測された数値やデータが正しいかどうか、改ざんされていないかについて一切責任を負いません。表示されるのは、GitHub で公開されているソースコードがアップロードされたデータから計算した結果であり、それ以上の保証はありません。",
