    "team.mitglieder" to "メンバー",
    "team.mitgliederAnzahl" to "メンバー {n} 人",
    "team.mitgliederSichtbar" to "メンバー一覧を見られるのは？",
    "team.name" to "チーム名",
    "team.nichtGefunden" to "このチームは存在しないか、公開されていません。",
    "team.nurFuerMitglieder" to "このチームのランキングはメンバーのみ閲覧できます。",
    "team.oeffentlich" to "ランキングを公開",
    "team.oeffentlichBadge" to "ランキング公開中",
    "team.oeffentlichErstNachFreigabe" to "外観が承認された後に有効になります。",
    "team.oeffentlichText" to "ログインしていない人を含め、誰でもランキング（順位・表示名・記録値）を見られるようになります。セッション、スポット、プロフィール写真はログイン中のユーザーにのみ表示されます。",
    "team.platz1" to "1位",
    "team.platz2" to "2位",
    "team.platz3" to "3位",
    "team.podest.fahrer" to "ライダー",
    "team.podest.stumm" to "ミュート",
    "team.podest.ton" to "勝者のサウンドを再生",
    "team.primaer" to "メインチーム",
    "team.primaerHinweis" to "グローバルイベントでは1つのチームにのみカウントされます。イベントページで別のチームを選ばない限り、メインチームです。",
    "team.primaerSetzen" to "メインチームに設定",
    "team.profilHinweis" to "チームを作成・参加して、独自のランキングを運営できます。",
    "team.profilKnopf" to "チーム",
    "team.qr" to "QRコード",
    "team.qrLaden" to "QRコードを保存",
    "team.qrTeilen" to "QRコードを共有",
    "team.regeln.beitreten.text" to "チームが参加を受け付けている場合、そのページに「参加」ボタンがあります。設定によって、すぐにメンバーになるか、リーダーまたはモデレーターが判断します。\n招待リンクは2つあります：すぐにメンバーになれるリンクと、申請を送るリンクです。どちらも QR コードとしても使えます。\nアカウントを持っていない人は作成すれば、そのままチームに入るか、申請が送られた状態になります。\n新しく作ったリンクは古いリンクに置き換わり、古いリンクは使えなくなります。\n参加するたびに、チームのランキングが公開される可能性があることに同意したことになります。今は公開されていなくても同じです。\n申請時には、これまでにどのスポットでどの種目をしたか（セッション数のみ）がリーダーとモデレーターに表示されます。",
    "team.regeln.beitreten.titel" to "参加",
    "team.regeln.bestenlisten.text" to "1人につき1件だけが集計されます：1つのセッションでのベスト値、または合計の場合は選択した期間内のすべての合算です。\nメンバーのすべてのセッションが対象で、参加前のものも含まれます。退出した人はすぐにランキングから消えます。\nイベントでは終了時点までに限ります（「イベント」を参照）。\nコミュニティの記録と同じフィルターが適用されます：削除された記録、報告された記録、競技が未設定の記録、記録中のものは集計されません。\n各ランキングは、1つの競技、1つのフォイルの範囲、モーションデータのある記録、スマホをボードに装着した記録、またはチームスポットに限定できます。\n「場所を隠す」がオンの場合、そのセッションが特定のスポットで集計されることはありません。\n同じ値の場合は、先にその値を出した人が上位になります。",
    "team.regeln.bestenlisten.titel" to "ランキング",
    "team.regeln.chat.text" to "チームチャットを読んだり書いたりできるのは、アクティブなメンバーだけです。申請しただけの人には表示されません。\n他の人にはどこにも表示されず、アクティブなチャットの一覧にも出てきません。\n退出した人や削除された人は、すぐにアクセスできなくなり、通知も届かなくなります。",
    "team.regeln.chat.titel" to "チームチャット",
    "team.regeln.events.text" to "イベントには期間と独自のランキングがあり、特定のスポットに限定することもできます。\nランキングに加えて、またはその代わりに、イベントでは参加者全員の合計（チーム全体のパンプ数や距離など）を表示できます。各イベントにはランキングか合計が少なくとも1つ必要です。\n期間内に開始したセッションだけが集計されます。\nリーダーはイベントごとに、手動でアップロードしたファイル（FIT・GPX・TCX）を集計しないよう設定できます。ウォッチ、アプリ、連携アカウントの記録は引き続き集計されます。\n終了後も4時間はアップロードでき、その間チームページには「集計中」と表示されます。その後、結果は確定され、後からトリミングや削除をしても何も変わりません。\n終了後に退出した人は結果に残り、その後に参加した人は加わりません。\n結果は毎晩確定されるほか、誰かがチームページを開いた時点でも確定されます。\n時刻はイベントを作成したタイムゾーンのもので、全員にそのまま表示されます。\n1位から3位にはフォイラーページにイベントバッジが付きますが、外観が承認されたチームに限ります。",
    "team.regeln.events.titel" to "イベント",
    "team.regeln.global.text" to "グローバルイベントはpumpfoil.org自身が主催します。期間内に条件に合うセッションがある人は、チーム参加や申し込みなしで自動的に対象になります。\n参加したくない人は、プロフィールの「プライバシー」で「グローバルイベントに参加しない」をオンにします。するとランキング、チーム順位、合計、バッジから外れ、終了済みのイベントからも消えます。\n各ランキングにはチームランキングがあります。各チームの上位メンバー（通常5人）の合計で、スピード（スプリント）は平均です。参加するのは承認済みでランキングを公開しているチームです。複数のチームに所属している人は1チームにのみカウントされます：イベントページで選んだチーム、なければメインチーム（★、チームページまたは「マイチーム」で設定）です。自分で選んでいない場合、別のチームに参加しても今のチームがメインのまま残り、新しいチームや大きくなったチームが自動で入れ替わることはありません。集計されない自分のチーム（未承認、またはランキング非公開）は、イベントページでグレー表示されます。イベント終了の6時間前まで変更できます。\nランキングはイベントリンクからログインなしでも見られます：順位、表示名、イニシャル、値。\nそれ以外はイベントのルールが適用されます：期間、集計、確定、1〜3位のバッジ（プロフィールページに「Global」と表示）。",
    "team.regeln.global.titel" to "グローバルイベント",
    "team.regeln.intro" to "pumpfoil.org のチームの仕組み：誰が何を見られるか、どう集計されるか、削除するとどうなるか。",
    "team.regeln.konto.text" to "その人はすべてのチームとランキングから消え、確定済みのイベント結果からも消えます。下の順位の人が繰り上がります。\nその人がチームのリーダーだった場合は、最も古くからいるモデレーターが引き継ぎ、いなければ最も古くからいるメンバーが引き継ぎます。誰も残っていなければ、チームは削除されます。",
    "team.regeln.konto.titel" to "アカウントが削除されたとき",
    "team.regeln.link" to "チームのルール",
    "team.regeln.loeschen.text" to "チームを削除できるのはリーダーだけで、確認のためにチーム名を入力する必要があります。\n削除するとチームは全員から見えなくなります：メンバー、ランキング、ログブック、イベント、チームチャット。誤って削除したチームを復元できるよう、データは当面保管します。\nチームのアドレスはロックされたままで、他のチームに割り当てられることはありません。",
    "team.regeln.loeschen.titel" to "チームの削除",
    "team.regeln.logbuch.text" to "ログブックには、誰が、いつ、どのチーム記録を更新したかが残ります。毎晩更新されます。\nランキングの最初の記録は、作成後最初の夜の時点の状況です。\nベスト値では、自分の記録の更新も含めて、すべての向上が記録されます。合計では、誰かがトップに立ったときだけ記録されます。\nセッションが削除されたり誰かが退出したりして記録が下がった場合は、記録を残さずに静かに修正されます。",
    "team.regeln.logbuch.titel" to "ログブック",
    "team.regeln.oeffentlich.text" to "チーム内では何をしても構いません。外部に表示されるのは、名前、アドレス、説明、エンブレム、カラーを私たちが一度確認して承認した後です。\nチームバナーはエンブレムと同じ承認を通ります。どの部分を見せるかはリーダーが新たな承認なしで選べます。バナーを削除すると、公開ページからもすぐに消えます。\n承認済みのチームが外観を変更すると、チーム内ではすぐに反映され、外部には改めて承認された後に反映されます。\n承認済みのチームは「すべてのチーム」ページに掲載されます。チームのイベントはチームページにあり、コミュニティにはpumpfoil.orgのグローバルイベントだけが表示されます。\nリーダーがランキングを公開すると、ログインしていない人も含めて誰でも見られますが、表示されるのは順位、表示名、イニシャル、記録値だけです。セッション、スポット、日付、プロフィール写真はログイン中のユーザーにのみ表示されます。\nチームページは検索エンジンに登録されません。\nメンバー一覧を見られる人はリーダーが決めます：メンバーのみ、またはログイン中のユーザー全員です。",
    "team.regeln.oeffentlich.titel" to "公開されるもの",
    "team.regeln.rollen.text" to "リーダーはすべてを行えます：設定、ランキング、イベント、モデレーターの指名、リーダーの引き継ぎ、チームの削除。\nモデレーターは申請を承認または却下し、メンバーを削除し、イベントを作成します。それ以外は変更できません。\nメンバーはチーム内のすべてを見られ、いつでも退出できます。\nリーダーは、リーダーを引き継いだ後でなければ退出できません。",
    "team.regeln.rollen.titel" to "役割",
    "team.regeln.statistik.text" to "ランキングの上には、選択した期間内の全メンバーの合計が表示されます：ポンプ、オンフォイル距離と時間、セッション、ラン、そしてアクティブだったメンバーの数です。\nチーム対チーム：コミュニティのチームランキングでは、ランキングを公開している承認済みのすべてのチームを、指標ごとに上位3人・5人・10人の合計で比べます。そこではすべてのチームに同じ基準が適用され、各チームのランキングのフィルターは使われません。\n2つのチームに所属している人は、両方のチームに加算されます。",
