    "team.primaer" to "主队",
    "team.primaerHinweis" to "在全球活动中你只为一个队伍计分：你的主队，除非你在活动页面选择其他队伍。",
    "team.primaerSetzen" to "设为主队",
    "team.profilHinweis" to "创建或加入团队，拥有自己的排行榜。",
    "team.profilKnopf" to "团队",
    "team.qr" to "二维码",
    "team.qrLaden" to "保存二维码",
    "team.qrTeilen" to "分享二维码",
    "team.regeln.beitreten.text" to "如果团队开放报名，其页面上会有“加入”按钮。根据设置，你会立即成为成员，或者由负责人或管理员决定。\n邀请链接有两个：一个让你立即成为成员，另一个用于发送申请。两者也都提供二维码。\n还没有账号的人创建账号后，就会直接进入团队，或者已经发出了申请。\n新生成的链接会取代旧链接，旧链接随即失效。\n每次加入时，你都同意团队的排行榜可以公开，即使它们目前并未公开。\n提交申请时，负责人和管理员会看到你目前去过哪些地点、从事过哪些运动（仅显示记录次数）。",
    "team.regeln.beitreten.titel" to "加入",
    "team.regeln.bestenlisten.text" to "每人只计一次：取其单条记录中的最佳值，如果是总计，则把所选时间段内的全部相加。\n成员的所有记录都计入，包括加入之前的。退出的人会立即从榜单上消失。\n对活动而言，这只在结束前适用，见“活动”。\n适用与社区纪录相同的过滤规则：已删除、被举报、未归类和仍在进行中的记录不计入。\n每个排行榜都可以限定为某一项运动、某一水翼范围、带运动数据的记录、手机装在板上的记录或团队地点。\n如果开启了“隐藏地点”，该记录永远不会计入任何特定地点。\n数值相同时，先达到该数值的人排在前面。",
    "team.regeln.bestenlisten.titel" to "排行榜",
    "team.regeln.chat.text" to "只有活跃成员才能阅读和发送团队聊天消息。只发出申请的人看不到它。\n它不会在任何地方向其他人显示，在活跃聊天中也不会出现。\n退出或被移除的人会立即失去访问权限，也不会再收到通知。",
    "team.regeln.chat.titel" to "团队聊天",
    "team.regeln.events.text" to "活动有一个时间窗口和自己的排行榜，也可以只限某些地点。\n除排行榜之外或代替排行榜，活动可以显示所有参与者的总计，例如整个团队的 pump 次数或距离。每个活动至少需要一个排行榜或一项总计。\n只有在时间窗口内开始的记录才计入。\n负责人可以为每个活动设定不统计手动上传的文件（FIT、GPX、TCX）；手表、App 和已关联账户的记录仍然计入。\n结束后仍可在 4 小时内上传，此时团队页面显示“结果统计中”。之后结果被冻结，之后再裁剪或删除都不会改变任何内容。\n结束后退出的人仍保留在结果中；之后加入的人不会再被计入。\n冻结在夜间进行，此外只要有人打开团队页面也会立即冻结。\n时间以创建活动时所在的时区为准，并以此向所有人显示。\n第 1 至 3 名会在自己的玩家主页上获得活动徽章，但仅限外观已获批准的团队。",
    "team.regeln.events.titel" to "活动",
    "team.regeln.global.text" to "全球活动由 pumpfoil.org 自己举办。只要在活动时间内有符合条件的会话，就会自动计入，无需加入团队，也无需报名。\n不想参加的人，可以在个人资料的“隐私”中打开“不参加全球活动”。之后他会从排行榜、团队排名、汇总和徽章中消失，已结束的活动也一样。\n每个排行榜都有队伍排名：每支队伍最佳成员（通常5人）的总和，速度类（冲刺）则取平均值。参与的是已批准且排行榜公开的队伍。加入多个队伍的人只为一个队伍计分：在活动页面选择的队伍，否则为主队（★，在队伍页面或“我的队伍”中设置）。如果没有自己选择，加入新队伍时原来的队伍仍是主队——新的或变大的队伍永远不会自动接替。不计分的自己的队伍（未获批准或排行榜未公开）在活动页面上以灰色显示。活动结束前6小时内不可再更改。\n排行榜也可以通过活动链接在未登录时查看：名次、显示名、首字母和数值。\n其余适用活动规则：时间范围、结算、冻结，以及第 1 至 3 名的徽章，在个人主页上标为“Global”。",
    "team.regeln.global.titel" to "全球活动",
    "team.regeln.intro" to "pumpfoil.org 上的团队是这样运作的：谁能看到什么、如何计分，以及删除时会发生什么。",
    "team.regeln.konto.text" to "此人会从所有团队和排行榜中消失，也会从已冻结的活动结果中消失。排在其后的人依次上移。\n如果此人是某个团队的负责人，由资历最久的管理员接任，否则由资历最久的成员接任。如果已经没有人了，团队就会被删除。",
    "team.regeln.konto.titel" to "账号被删除时",
    "team.regeln.link" to "团队规则",
    "team.regeln.loeschen.text" to "只有负责人可以删除团队，而且必须输入团队名称进行确认。\n之后团队对所有人消失：成员、排行榜、日志、活动和团队聊天。我们暂时保留数据，以便恢复误删的团队。\n团队的地址会保持锁定，永远不会分配给其他团队。",
    "team.regeln.loeschen.titel" to "删除团队",
    "team.regeln.logbuch.text" to "日志记录谁在何时打破了哪项团队纪录。每晚更新。\n排行榜的第一条日志是创建后第一个夜晚的状态。\n对于最佳值，每一次提升都会记录，包括刷新自己的纪录。对于总计，只有当有人登上榜首时才会记录。\n如果因为某条记录被删除或有人退出而导致纪录下降，会悄悄调整，不留日志。",
    "team.regeln.logbuch.titel" to "日志",
    "team.regeln.oeffentlich.text" to "在团队内部可以随意设置。只有在我们查看并批准了团队的名称、地址、简介、队徽和颜色之后，它才会对外显示。\n团队横幅与队徽经过同样的审核。显示哪一部分由负责人选择，无需重新审核；若移除横幅，它也会立即从公开页面消失。\n已获批准的团队如果更改外观，在团队内会立即生效，对外则要在重新批准后才生效。\n已获批准的团队列在“所有团队”页面。团队的活动在团队页面上；社区里只显示 pumpfoil.org 的全球活动。\n如果负责人将排行榜设为公开，所有人都能看到，即使未登录，但只显示名次、显示名称、姓名首字母和数值。记录、地点、日期和头像只有已登录用户才能看到。\n搜索引擎不会收录团队页面。\n谁能看到成员列表由负责人决定：仅成员，或所有已登录用户。",
    "team.regeln.oeffentlich.titel" to "哪些内容是公开的",
    "team.regeln.rollen.text" to "负责人可以做所有事：设置、排行榜、活动、任命管理员、移交负责人身份以及删除团队。\n管理员负责接受或拒绝申请、移除成员以及创建活动。除此之外不能更改任何内容。\n成员可以看到团队内的一切，并且随时可以退出。\n负责人只有在移交负责人身份之后才能退出。",
    "team.regeln.rollen.titel" to "角色",
    "team.regeln.statistik.text" to "排行榜上方显示所选时间段内全体成员的总计：泵动次数、上翼距离和时长、记录数、航段数以及有多少成员活跃。\n团队对团队：在社区中，团队排行榜比较所有排行榜公开且已获批准的团队，每项指标取最好的 3、5 或 10 名骑手之和。那里对所有团队采用同一标准，不使用各团队自己排行榜的筛选条件。\n同时在两个团队的人，两个团队都计入。",
