    "team.linkNeu" to "Создать новую ссылку",
    "team.linkNeuFrage" to "Создать новую ссылку? Текущая перестанет работать.",
    "team.links" to "Ссылки-приглашения",
    "team.linksHinweis" to "Две ссылки, чтобы раздавать. У кого ещё нет аккаунта, создаёт его и сразу оказывается в команде.",
    "team.loeschen" to "Удалить команду",
    "team.loeschenKnopf" to "Удалить окончательно",
    "team.loeschenText" to "Команда сразу пропадёт для всех вместе с таблицами, событиями и чатом. Данные мы пока сохраняем, чтобы случайно удалённую команду можно было восстановить. Для подтверждения введи название команды «{name}».",
