    "team.mitgliederAnzahl" to "Участники: {n}",
    "team.mitgliederSichtbar" to "Кто видит список участников?",
    "team.name" to "Название команды",
    "team.nichtGefunden" to "Такой команды нет, или она не публичная.",
    "team.nurFuerMitglieder" to "Таблицы лидеров этой команды видят только участники.",
    "team.oeffentlich" to "Публичные таблицы лидеров",
    "team.oeffentlichBadge" to "Публичные таблицы лидеров",
    "team.oeffentlichErstNachFreigabe" to "Действует только после одобрения оформления.",
    "team.oeffentlichText" to "Тогда таблицы лидеров видят все, даже без входа: место, отображаемое имя и значение. Сессии, споты и фото профиля видят только вошедшие пользователи.",
    "team.platz1" to "1-е место",
    "team.platz2" to "2-е место",
    "team.platz3" to "3-е место",
    "team.podest.fahrer" to "Райдеры",
    "team.podest.stumm" to "Без звука",
    "team.podest.ton" to "Включить звук победителя",
    "team.primaer" to "Основная команда",
    "team.primaerHinweis" to "В глобальных событиях ты засчитываешься только за одну команду: основную, если на странице события не выберешь другую.",
    "team.primaerSetzen" to "Сделать основной командой",
    "team.profilHinweis" to "Создавай команды, вступай в них и веди свои таблицы лидеров.",
    "team.profilKnopf" to "Команда",
    "team.qr" to "QR-код",
    "team.qrLaden" to "Сохранить QR-код",
    "team.qrTeilen" to "Поделиться QR-кодом",
    "team.regeln.beitreten.text" to "Если команда принимает заявки, на её странице есть кнопка «Вступить». В зависимости от настройки ты сразу становишься участником, или решает руководитель либо модератор.\nЕсть две ссылки-приглашения: по одной ты сразу становишься участником, по другой отправляешь заявку. Обе есть и в виде QR-кода.\nУ кого ещё нет аккаунта, создаёт его и после этого сразу оказывается в команде или уже отправил заявку.\nНовая ссылка заменяет старую, и старая перестаёт действовать.\nПри каждом вступлении ты соглашаешься с тем, что таблицы лидеров команды могут быть публичными, даже если сейчас это не так.\nПри заявке руководитель и модераторы видят, на каких спотах и в каких видах спорта ты катался до сих пор (только число сессий).",
    "team.regeln.beitreten.titel" to "Вступление",
    "team.regeln.bestenlisten.text" to "Каждый человек учитывается только один раз: его лучшее значение из одной сессии, а для сумм — всё за выбранный период вместе.\nУчитываются все сессии участников, в том числе до вступления. Кто выходит из команды, сразу исчезает из таблиц.\nДля событий это действует только до конца, см. «События».\nДействуют те же фильтры, что и для рекордов сообщества: удалённые, отмеченные жалобой, не отнесённые к виду спорта и ещё идущие записи не учитываются.\nКаждую таблицу лидеров можно ограничить одним видом спорта, одним диапазоном фойлов, записями с данными движения, телефоном на доске или спотами команды.\nЕсли включено «Скрыть место», сессия никогда не учитывается для конкретного спота.\nПри равенстве выше тот, кто показал результат первым.",
    "team.regeln.bestenlisten.titel" to "Таблицы лидеров",
    "team.regeln.chat.text" to "Читать и писать в чат команды могут только активные участники. Кто только отправил заявку, его не видит.\nДля остальных он нигде не появляется, даже среди активных чатов.\nКто выходит из команды или кого убирают, сразу теряет доступ и больше не получает уведомлений.",
    "team.regeln.chat.titel" to "Чат команды",
    "team.regeln.events.text" to "У события есть временное окно и свои таблицы лидеров, по желанию только на определённых спотах.\nПомимо таблиц лидеров или вместо них событие может показывать суммы по всем участникам, например пампы или дистанцию всей команды. Каждому событию нужна хотя бы одна таблица или одна сумма.\nУчитываются только сессии, начатые в этом окне.\nДля каждого события руководитель может решить, что вручную загруженные файлы (FIT, GPX, TCX) не учитываются; записи с часов, из приложения и привязанных аккаунтов по-прежнему учитываются.\nПосле окончания можно ещё 4 часа загружать записи, страница команды тогда показывает «подведение итогов». Затем результат замораживается, и последующая обрезка или удаление уже ничего не меняют.\nКто выходит после окончания, остаётся в результате; кто вступает позже, уже не добавляется.\nРезультаты замораживаются ночью, а также сразу, как только кто-то откроет страницу команды.\nВремя указано в часовом поясе, в котором создано событие, и так же показывается всем.\nМеста с 1 по 3 получают значок события на своей странице фойлера, но только в командах с одобренным оформлением.",
    "team.regeln.events.titel" to "События",
    "team.regeln.global.text" to "Глобальные события проводит сам pumpfoil.org. Автоматически учитывается каждый с подходящими сессиями в рамках события, без вступления и без регистрации.\nКто не хочет участвовать, отключает это в профиле в разделе «Конфиденциальность» («Не участвовать в глобальных событиях»). Тогда он пропадает из таблиц, командного зачёта, сумм и значков, в том числе в уже завершённых событиях.\nУ каждой таблицы есть командный зачёт: сумма лучших участников каждой команды, обычно 5, а для скоростей (спринтов) — их среднее. Участвуют одобренные команды с публичными таблицами. Кто состоит в нескольких командах, засчитывается только за одну: за выбранную на странице события, иначе — за основную (★, задаётся на странице команды или в «Мои команды»). Без собственного выбора при вступлении в ещё одну команду основной остаётся прежняя — новая или выросшая команда никогда не заменяет её сама. Свои команды, которые не учитываются (не одобрены или с непубличными таблицами), показаны на странице события серым. Изменить можно не позднее чем за 6 часов до конца события.\nТаблицы видны и без входа по ссылке на событие: место, отображаемое имя, инициалы и значение.\nВ остальном действуют правила событий: время события, подведение итогов, фиксация и значки за места с 1 по 3, отмеченные на странице профиля как «Global».",
    "team.regeln.global.titel" to "Глобальные события",
    "team.regeln.intro" to "Как устроены команды на pumpfoil.org: кто что видит, как считаются результаты и что происходит при удалении.",
    "team.regeln.konto.text" to "Человек исчезает из всех команд и таблиц лидеров, а также из замороженных результатов событий. Те, кто ниже, поднимаются на место выше.\nЕсли он руководил командой, руководство переходит к модератору с самым большим стажем, иначе к участнику с самым большим стажем. Если никого не осталось, команда удаляется.",
    "team.regeln.konto.titel" to "Когда удаляется аккаунт",
    "team.regeln.link" to "Правила команд",
    "team.regeln.loeschen.text" to "Удалить команду может только руководитель, и только введя для подтверждения название команды.\nПосле этого команда пропадает для всех: участие, таблицы, журнал, события и чат команды. Данные мы пока сохраняем, чтобы случайно удалённую команду можно было восстановить.\nАдрес команды остаётся заблокированным и никогда не передаётся другой команде.",
    "team.regeln.loeschen.titel" to "Удаление команды",
    "team.regeln.logbuch.text" to "Журнал фиксирует, кто и когда побил какой рекорд команды. Он обновляется каждую ночь.\nПервая запись таблицы лидеров — это положение в первую ночь после её создания.\nДля лучших значений считается каждое улучшение, в том числе собственное. Для сумм — только когда кто-то выходит в лидеры.\nЕсли рекорд снижается, потому что сессию удалили или кто-то вышел из команды, это тихо исправляется, без записи.",
    "team.regeln.logbuch.titel" to "Журнал",
    "team.regeln.oeffentlich.text" to "Внутри команда может всё. Для остальных она появляется, только когда мы один раз посмотрели и одобрили её название, адрес, описание, эмблему и цвет.\nБаннер команды проходит ту же проверку, что и эмблема. Какую часть видно, руководитель выбирает без новой проверки; если баннер удалить, он сразу пропадает и с публичной страницы.\nЕсли одобренная команда меняет оформление, в команде это действует сразу, а для остальных — только после нового одобрения.\nОдобренные команды перечислены на странице «Все команды». Их события находятся на странице команды; в сообществе показаны только глобальные события pumpfoil.org.\nЕсли руководитель делает таблицы лидеров публичными, их видят все, даже без входа, но только место, отображаемое имя, инициалы и значение. Сессии, споты, даты и фото профиля видят только вошедшие пользователи.\nПоисковые системы не индексируют страницы команд.\nКто видит список участников, решает руководитель: только участники или все вошедшие пользователи.",
    "team.regeln.oeffentlich.titel" to "Что видно публично",
    "team.regeln.rollen.text" to "Руководитель может всё: настройки, таблицы лидеров, события, назначение модераторов, передачу руководства и удаление команды.\nМодераторы принимают или отклоняют заявки, убирают участников и создают события. Больше они ничего не меняют.\nУчастники видят в команде всё и могут выйти из неё в любой момент.\nРуководитель может выйти, только передав руководство.",
    "team.regeln.rollen.titel" to "Роли",
    "team.regeln.statistik.text" to "Над таблицами лидеров показаны суммы по всем участникам за выбранный период: помпинг, дистанция и время на фойле, сессии, заезды и сколько участников были активны.\nКоманда против команды: в сообществе таблицы команд сравнивают все одобренные команды с публичными таблицами, по каждому показателю суммой лучших 3, 5 или 10 райдеров. Там для всех команд действует одна мерка, а не фильтры их собственных таблиц.\nКто состоит в двух командах, засчитывается за обе.",
    "team.regeln.statistik.titel" to "Итоги команды",
    "team.regeln.titel" to "Правила команд",
    "team.regeln.was.text" to "Постоянная группа со своими таблицами лидеров, событиями и чатом команды.\nЛюбой может создавать команды, в том числе несколько, и состоять в нескольких командах.\nНовая команда работает сразу, через ссылки-приглашения.",
    "team.regeln.was.titel" to "Что такое команда?",
    "team.rolle.leiter" to "Руководитель",
    "team.rolle.mitglied" to "Участник",
