    "team.linkNeuFrage" to "Buat tautan baru? Tautan yang sekarang tidak akan berfungsi lagi.",
    "team.links" to "Tautan undangan",
    "team.linksHinweis" to "Dua tautan untuk dibagikan. Yang belum punya akun membuat akun dulu, lalu langsung masuk tim.",
    "team.loeschen" to "Hapus tim",
    "team.loeschenKnopf" to "Hapus permanen",
    "team.loeschenText" to "Tim langsung hilang untuk semua orang, beserta papan peringkat, event, dan chat tim. Untuk sementara kami menyimpan datanya agar tim yang terhapus tanpa sengaja bisa dipulihkan. Untuk konfirmasi, ketik nama tim “{name}”.",
