    "team.logbuchHinweis" to "Siapa memecahkan rekor tim yang mana, dan kapan. Diperbarui setiap malam.",
    "team.logbuchLeer" to "Belum ada entri. Klasemen pertama muncul pada malam setelah papan peringkat dibuat.",
    "team.logoHochladen" to "Unggah lambang",
    "team.meine" to "Tim saya",
    "team.mitglieder" to "Anggota",
    "team.mitgliederAnzahl" to "{n} anggota",
    "team.mitgliederSichtbar" to "Siapa yang bisa melihat daftar anggota?",
    "team.name" to "Nama tim",
    "team.nichtGefunden" to "Tim ini tidak ada atau tidak publik.",
    "team.nurFuerMitglieder" to "Hanya anggota yang bisa melihat papan peringkat tim ini.",
    "team.oeffentlich" to "Papan peringkat publik",
    "team.oeffentlichBadge" to "Papan peringkat publik",
    "team.oeffentlichErstNachFreigabe" to "Berlaku setelah tampilan disetujui.",
    "team.oeffentlichText" to "Semua orang bisa melihat papan peringkat, bahkan tanpa masuk: peringkat, nama tampilan, dan nilai. Sesi, spot, dan foto profil tetap hanya terlihat oleh pengguna yang sudah masuk.",
    "team.platz1" to "Juara 1",
    "team.platz2" to "Juara 2",
    "team.platz3" to "Juara 3",
    "team.podest.fahrer" to "Pengendara",
    "team.podest.stumm" to "Bisukan",
    "team.podest.ton" to "Putar suara pemenang",
    "team.primaer" to "Tim utama",
    "team.primaerHinweis" to "Di event global kamu hanya dihitung untuk satu tim: tim utamamu, kecuali kamu memilih tim lain di halaman event.",
    "team.primaerSetzen" to "Jadikan tim utama",
    "team.profilHinweis" to "Buat tim atau gabung ke tim dengan papan peringkat sendiri.",
    "team.profilKnopf" to "Tim",
    "team.qr" to "Kode QR",
    "team.qrLaden" to "Simpan kode QR",
    "team.qrTeilen" to "Bagikan kode QR",
    "team.regeln.beitreten.text" to "Jika tim menerima pendaftaran, halamannya menampilkan tombol “Gabung”. Tergantung pengaturan, kamu langsung jadi anggota, atau ketua tim atau moderator yang memutuskan.\nAda dua tautan undangan: satu yang langsung menjadikanmu anggota dan satu yang mengirim permintaan. Keduanya juga tersedia sebagai kode QR.\nYang belum punya akun membuat akun dulu, lalu langsung masuk tim atau permintaannya sudah terkirim.\nTautan yang baru dibuat menggantikan yang lama, dan yang lama tidak berlaku lagi.\nSetiap kali bergabung, kamu setuju bahwa papan peringkat tim boleh dibuat publik, meski saat ini tidak.\nSaat mengajukan permintaan, ketua dan moderator melihat di spot mana dan olahraga apa saja kamu pernah bermain sejauh ini (hanya jumlah sesi).",
    "team.regeln.beitreten.titel" to "Bergabung",
    "team.regeln.bestenlisten.text" to "Setiap orang dihitung sekali: nilai terbaiknya dari satu sesi, atau untuk total, semua yang dicapai dalam periode yang dipilih dijumlahkan.\nSemua sesi anggota dihitung, termasuk yang dari sebelum bergabung. Yang keluar langsung hilang dari daftar.\nUntuk event, ini hanya berlaku sampai selesai, lihat “Event”.\nFilternya sama dengan rekor komunitas: rekaman yang dihapus, dilaporkan, belum ditetapkan, dan masih berlangsung tidak dihitung.\nSetiap papan peringkat bisa dibatasi ke satu olahraga, rentang foil, rekaman dengan data gerak, ponsel di papan, atau spot tim.\nJika “Sembunyikan lokasi” aktif, sesi itu tidak pernah dihitung untuk spot tertentu.\nJika nilainya sama, yang lebih dulu mencapai nilai itu ada di depan.",
    "team.regeln.bestenlisten.titel" to "Papan peringkat",
    "team.regeln.chat.text" to "Hanya anggota aktif yang bisa membaca dan menulis di chat tim. Yang baru mengirim permintaan tidak bisa melihatnya.\nChat ini tidak muncul di mana pun bagi orang lain, bahkan tidak di daftar chat aktif.\nYang keluar atau dikeluarkan langsung kehilangan akses dan tidak lagi menerima notifikasi.",
    "team.regeln.chat.titel" to "Chat tim",
    "team.regeln.events.text" to "Event punya rentang waktu dan papan peringkat sendiri, kalau mau hanya di spot tertentu.\nSelain papan peringkat, atau sebagai gantinya, event dapat menampilkan total dari semua peserta, misalnya pump atau jarak seluruh tim. Setiap event memerlukan minimal satu papan peringkat atau satu total.\nHanya sesi yang dimulai dalam rentang waktu itu yang dihitung.\nUntuk setiap event, ketua dapat menetapkan bahwa file yang diunggah manual (FIT, GPX, TCX) tidak dihitung; rekaman dari jam, aplikasi, dan akun tertaut tetap dihitung.\nSetelah selesai, kamu masih bisa mengunggah selama 4 jam; halaman tim lalu menampilkan “menunggu hasil”. Setelah itu hasilnya dibekukan, dan memotong atau menghapus belakangan tidak mengubah apa pun lagi.\nYang keluar setelah selesai tetap ada di hasil; yang bergabung sesudahnya tidak ikut lagi.\nHasil dibekukan pada malam hari dan juga begitu seseorang membuka halaman tim.\nWaktunya mengikuti zona waktu tempat event dibuat dan ditampilkan begitu untuk semua orang.\nPeringkat 1 sampai 3 mendapat lencana event di halaman foiler mereka, tapi hanya untuk tim yang tampilannya sudah disetujui.",
    "team.regeln.events.titel" to "Event",
    "team.regeln.global.text" to "Event global diselenggarakan oleh pumpfoil.org sendiri. Siapa pun yang punya sesi yang cocok dalam rentang waktu otomatis dihitung, tanpa bergabung dan tanpa mendaftar.\nYang tidak ingin ikut bisa mematikannya di profil pada “Privasi” (“Jangan ikut event global”). Maka ia tidak muncul di papan peringkat, peringkat tim, total, dan lencana, juga di event yang sudah selesai.\nSetiap papan peringkat punya peringkat tim: jumlah anggota terbaik tiap tim, biasanya 5, dan untuk kecepatan (sprint) rata-ratanya. Tim yang disetujui dengan papan peringkat publik ikut serta. Yang ada di beberapa tim hanya dihitung untuk satu: tim yang dipilih di halaman event, jika tidak maka tim utamanya (★, diatur di halaman tim atau di “Tim saya”). Tanpa pilihan sendiri, saat bergabung ke tim lain tim yang sekarang tetap menjadi tim utama – tim baru atau yang membesar tidak pernah mengambil alih dengan sendirinya. Tim sendiri yang tidak dihitung (belum disetujui atau papan peringkat tidak publik) tampil abu-abu di halaman event. Bisa diubah sampai 6 jam sebelum event berakhir.\nPapan peringkat juga terlihat tanpa login lewat tautan event: peringkat, nama tampilan, inisial, dan nilai.\nSelebihnya berlaku aturan event: rentang waktu, penilaian, pembekuan, dan lencana untuk peringkat 1 sampai 3, ditandai “Global” di halaman profil.",
    "team.regeln.global.titel" to "Event global",
    "team.regeln.intro" to "Begini cara kerja tim di pumpfoil.org: siapa melihat apa, bagaimana peringkat dihitung, dan apa yang terjadi saat sesuatu dihapus.",
    "team.regeln.konto.text" to "Orang itu hilang dari semua tim dan papan peringkat, juga dari hasil event yang sudah dibekukan. Yang di bawahnya naik peringkat.\nJika ia memimpin tim, moderator paling lama mengambil alih, jika tidak ada maka anggota paling lama. Jika tidak ada siapa pun lagi, tim dihapus.",
    "team.regeln.konto.titel" to "Saat akun dihapus",
    "team.regeln.link" to "Aturan tim",
    "team.regeln.loeschen.text" to "Hanya ketua tim yang bisa menghapus tim, dan hanya dengan mengetik nama tim sebagai konfirmasi.\nSetelah itu tim hilang untuk semua orang: keanggotaan, papan peringkat, buku log, event, dan chat tim. Untuk sementara kami menyimpan datanya agar tim yang terhapus tanpa sengaja bisa dipulihkan.\nAlamat tim tetap diblokir dan tidak pernah diberikan ke tim lain.",
    "team.regeln.loeschen.titel" to "Menghapus tim",
    "team.regeln.logbuch.text" to "Buku log mencatat siapa memecahkan rekor tim yang mana, dan kapan. Diperbarui setiap malam.\nEntri pertama sebuah papan peringkat adalah posisi pada malam pertama setelah papan itu dibuat.\nUntuk nilai terbaik, setiap peningkatan dihitung, termasuk milik sendiri. Untuk total, hanya dihitung saat seseorang mengambil alih posisi teratas.\nJika sebuah rekor turun karena sesi dihapus atau seseorang keluar, rekor itu disesuaikan diam-diam, tanpa entri.",
    "team.regeln.logbuch.titel" to "Buku log",
    "team.regeln.oeffentlich.text" to "Di dalam, tim boleh melakukan apa saja. Tim baru tampil ke luar setelah kami memeriksa dan menyetujui nama, alamat, deskripsi, lambang, dan warnanya.\nBanner tim melewati persetujuan yang sama dengan lambang. Bagian mana yang terlihat dipilih ketua tanpa persetujuan baru; jika banner dihapus, banner langsung hilang juga dari halaman publik.\nJika tim yang sudah disetujui mengubah tampilannya, perubahan langsung berlaku di dalam tim, dan untuk publik setelah disetujui lagi.\nTim yang sudah disetujui tercantum di halaman “Semua tim”. Event mereka ada di halaman tim; di komunitas hanya ada event global dari pumpfoil.org.\nJika ketua tim membuat papan peringkat publik, semua orang bisa melihatnya, bahkan tanpa masuk, tapi hanya peringkat, nama tampilan, inisial, dan nilai. Sesi, spot, tanggal, dan foto profil hanya terlihat oleh pengguna yang sudah masuk.\nMesin pencari tidak mengindeks halaman tim.\nKetua tim menentukan siapa yang melihat daftar anggota: hanya anggota atau semua pengguna yang sudah masuk.",
    "team.regeln.oeffentlich.titel" to "Apa yang publik",
    "team.regeln.rollen.text" to "Ketua tim boleh melakukan semuanya: pengaturan, papan peringkat, event, menunjuk moderator, menyerahkan kepemimpinan, dan menghapus tim.\nModerator menerima atau menolak permintaan, mengeluarkan anggota, dan membuat event. Selain itu mereka tidak mengubah apa pun.\nAnggota melihat semua hal di tim dan bisa keluar kapan saja.\nKetua tim baru bisa keluar setelah menyerahkan kepemimpinan.",
    "team.regeln.rollen.titel" to "Peran",
    "team.regeln.statistik.text" to "Di atas papan peringkat ada total semua anggota dalam periode yang dipilih: pump, jarak dan waktu on-foil, sesi, run, dan berapa anggota yang aktif.\nTim melawan tim: di komunitas, papan peringkat tim membandingkan semua tim yang disetujui dengan papan peringkat publik, per metrik dengan jumlah 3, 5, atau 10 rider terbaik. Di sana berlaku ukuran yang sama untuk semua tim, bukan filter papan peringkat mereka sendiri.\nYang ada di dua tim dihitung untuk keduanya.",
    "team.regeln.statistik.titel" to "Total tim",
    "team.regeln.titel" to "Aturan tim",
    "team.regeln.was.text" to "Kelompok tetap dengan papan peringkat, event, dan chat tim sendiri.\nSiapa pun bisa membuat tim, bahkan beberapa, dan bergabung di beberapa tim.\nTim baru langsung berfungsi, lewat tautan undangan.",
    "team.regeln.was.titel" to "Apa itu tim?",
    "team.rolle.leiter" to "Ketua",
    "team.rolle.mitglied" to "Anggota",
    "team.rolle.moderator" to "Moderator",
    "team.rolleUebergeben" to "Serahkan posisi ketua",
    "team.sichtbar.angemeldete" to "Semua pengguna yang sudah masuk",
