    "team.loeschenKnopf" to "Slett for godt",
    "team.loeschenText" to "Laget forsvinner straks for alle, med lister, arrangementer og lagchat. Vi tar vare på dataene inntil videre, så et lag som er slettet ved en feil kan gjenopprettes. Skriv lagnavnet «{name}» for å bekrefte.",
