    "team.logbuchHinweis" to "Hvem som slo hvilken lagrekord, og når. Oppdateres hver natt.",
    "team.logbuchLeer" to "Ingen oppføringer ennå. Den første stillingen kommer natten etter at topplistene er satt opp.",
