    "team.mitgliederSichtbar" to "Hvem ser medlemslisten?",
    "team.name" to "Lagnavn",
    "team.nichtGefunden" to "Dette laget finnes ikke, eller det er ikke offentlig.",
    "team.nurFuerMitglieder" to "Bare medlemmer ser topplistene til dette laget.",
