    "team.oeffentlichBadge" to "Offentlige topplister",
    "team.oeffentlichErstNachFreigabe" to "Gjelder først når utseendet er godkjent.",
    "team.oeffentlichText" to "Da ser alle topplistene, også uten innlogging: plass, visningsnavn og verdi. Økter, spots og profilbilder ser bare innloggede brukere.",
    "team.platz1" to "1. plass",
    "team.platz2" to "2. plass",
    "team.platz3" to "3. plass",
    "team.podest.fahrer" to "Utøvere",
    "team.podest.stumm" to "Lydløs",
    "team.podest.ton" to "Spill vinnerlyd",
    "team.primaer" to "Primærlag",
    "team.primaerHinweis" to "I globale eventer teller du bare for ett lag: primærlaget ditt, med mindre du velger et annet på eventsiden.",
    "team.primaerSetzen" to "Sett som primærlag",
    "team.profilHinweis" to "Start eller bli med i lag med egne topplister.",
    "team.profilKnopf" to "Lag",
    "team.qr" to "QR-kode",
    "team.qrLaden" to "Lagre QR-kode",
    "team.qrTeilen" to "Del QR-kode",
    "team.regeln.beitreten.text" to "Tar et lag imot påmeldinger, finnes det en «Bli med»-knapp på siden. Avhengig av innstillingen er du medlem med en gang, eller lederen eller en moderator bestemmer.\nDet finnes to invitasjonslenker: én som gjør deg til medlem med en gang, og én som sender en forespørsel. Begge finnes også som QR-kode.\nDen som ikke har konto, oppretter en og er deretter rett i laget, eller har sendt forespørselen.\nEn nylaget lenke erstatter den gamle, som da slutter å virke.\nHver gang du blir med, godtar du at lagets topplister kan være offentlige, også om de ikke er det akkurat nå.\nVed en forespørsel ser lederen og moderatorene hvilke spotter og idretter du har vært ute på så langt (bare antall økter).",
    "team.regeln.beitreten.titel" to "Bli med",
    "team.regeln.bestenlisten.text" to "Hver person teller bare én gang: sin beste verdi fra én økt, eller ved summer alt i valgt periode lagt sammen.\nAlle øktene til medlemmene teller, også de fra før innmeldingen. Den som melder seg ut, forsvinner fra listene med en gang.\nFor arrangementer gjelder det bare til slutten, se «Arrangementer».\nDe samme filtrene gjelder som for fellesskapsrekordene: slettede, rapporterte, ikke tilordnede og pågående opptak teller ikke.\nHver toppliste kan begrenses til én sport, ett foilområde, opptak med bevegelsesdata, telefon på brettet eller lagspotsene.\nEr «Skjul stedet» slått på, teller økten aldri for en bestemt spot.\nVed likt resultat ligger den foran som kjørte verdien først.",
    "team.regeln.bestenlisten.titel" to "Topplister",
    "team.regeln.chat.text" to "Bare aktive medlemmer kan lese og skrive i lagchatten. Den som bare har sendt en forespørsel, ser den ikke.\nDen dukker ikke opp noe sted for andre, heller ikke blant de aktive chattene.\nDen som melder seg ut eller blir fjernet, mister tilgangen med en gang og får ingen flere varsler.",
    "team.regeln.chat.titel" to "Lagchat",
    "team.regeln.events.text" to "Et arrangement har et tidsvindu og egne topplister, om ønskelig bare på bestemte spots.\nI tillegg til eller i stedet for topplister kan et arrangement vise totaler for alle deltakere, for eksempel pumpene eller distansen til hele laget. Hvert arrangement trenger minst én toppliste eller én total.\nBare økter som starter i tidsvinduet, teller.\nFor hvert arrangement kan lederen bestemme at manuelt opplastede filer (FIT, GPX, TCX) ikke teller; opptak fra klokker, appen og koblede kontoer teller fortsatt.\nEtter slutt kan du laste opp i 4 timer til, og lagsiden viser da «resultat ventes». Deretter er resultatet fryst, og senere trimming eller sletting endrer ingenting lenger.\nDen som melder seg ut etter slutten, blir stående i resultatet; den som blir med etterpå, kommer ikke med.\nResultatene fryses om natten og i tillegg så snart noen åpner lagsiden.\nTidene gjelder i tidssonen arrangementet ble opprettet i, og vises slik for alle.\nPlass 1 til 3 får et arrangementsmerke på foilersiden sin, men bare i lag der utseendet er godkjent.",
    "team.regeln.events.titel" to "Arrangementer",
    "team.regeln.global.text" to "Globale eventer arrangeres av pumpfoil.org selv. Alle med passende økter i tidsvinduet teller automatisk, uten å bli med og uten påmelding.\nDen som ikke vil delta, slår det av i profilen under «Personvern» («Ikke delta i globale eventer»). Da mangler man i topplister, lagkonkurranser, summer og merker, også i eventer som allerede er over.\nHver resultatliste har en lagkonkurranse: summen av de beste medlemmene i hvert lag, vanligvis 5, og for fart (sprinter) gjennomsnittet deres. Godkjente lag med offentlige resultatlister er med. Den som er i flere lag, teller bare for ett: laget som er valgt på eventsiden, ellers primærlaget sitt (★, satt på lagsiden eller under «Mine lag»). Uten eget valg forblir det nåværende laget primærlaget når du blir med i et nytt lag – et nytt eller større lag tar aldri over av seg selv. Egne lag som ikke teller (ikke godkjent eller resultatlistene ikke offentlige), vises grået ut på eventsiden. Det kan endres til 6 timer før eventet slutter.\nTopplistene er også synlige uten innlogging via eventlenken: plass, visningsnavn, initialer og verdi.\nEllers gjelder reglene for eventer: tidsvindu, resultat, frysing og merker for plass 1 til 3, merket «Global» på profilsiden.",
    "team.regeln.global.titel" to "Globale eventer",
    "team.regeln.intro" to "Slik fungerer lag på pumpfoil.org: hvem som ser hva, hvordan det telles, og hva som skjer ved sletting.",
    "team.regeln.konto.text" to "Personen forsvinner fra alle lag og topplister, også fra frosne arrangementsresultater. De nedenfor rykker opp.\nLedet personen et lag, tar moderatoren med lengst fartstid over, ellers medlemmet med lengst fartstid. Er det ingen igjen, slettes laget.",
    "team.regeln.konto.titel" to "Når en konto slettes",
    "team.regeln.link" to "Lagregler",
    "team.regeln.loeschen.text" to "Bare lederen kan slette laget, og bare ved å skrive inn lagnavnet som bekreftelse.\nDa er laget borte for alle: medlemskap, lister, loggbok, arrangementer og lagchatten. Vi tar vare på dataene inntil videre, så et lag som er slettet ved en feil kan gjenopprettes.\nAdressen til laget forblir sperret og gis aldri til et annet lag.",
    "team.regeln.loeschen.titel" to "Slette laget",
    "team.regeln.logbuch.text" to "Loggboken holder rede på hvem som slo hvilken lagrekord, og når. Den oppdateres hver natt.\nDen første oppføringen i en toppliste er stillingen den første natten etter at den ble opprettet.\nFor beste verdier teller hver forbedring, også din egen. For summer teller det bare når noen tar ledelsen.\nSynker en rekord fordi en økt ble slettet eller noen meldte seg ut, rettes det stille, uten oppføring.",
    "team.regeln.logbuch.titel" to "Loggbok",
    "team.regeln.oeffentlich.text" to "Internt kan et lag gjøre alt. Utad vises det først når vi har sett på og godkjent navn, adresse, beskrivelse, våpenskjold og farge.\nLagbanneret går gjennom samme godkjenning som våpenskjoldet. Hvilken del som vises, velger lederen uten ny godkjenning; fjerner lederen banneret, forsvinner det straks også fra den offentlige siden.\nEndrer et godkjent lag utseendet sitt, gjelder det i laget med en gang, utad først etter ny godkjenning.\nGodkjente lag står på siden «Alle lag». Eventene deres står på lagsiden; i fellesskapet står bare de globale eventene fra pumpfoil.org.\nGjør lederen topplistene offentlige, ser alle dem, også uten innlogging, men bare plass, visningsnavn, initialer og verdi. Økter, spots, datoer og profilbilder ser bare innloggede brukere.\nSøkemotorer indekserer ikke lagsider.\nLederen bestemmer hvem som ser medlemslisten: bare medlemmer eller alle innloggede.",
    "team.regeln.oeffentlich.titel" to "Hva som er offentlig",
    "team.regeln.rollen.text" to "Lederen kan gjøre alt: innstillinger, topplister, arrangementer, utnevne moderatorer, overlate lederrollen og slette laget.\nModeratorer godtar eller avslår forespørsler, fjerner medlemmer og oppretter arrangementer. Ellers endrer de ingenting.\nMedlemmer ser alt i laget og kan melde seg ut når som helst.\nLederen kan først melde seg ut etter å ha overlatt lederrollen.",
    "team.regeln.rollen.titel" to "Roller",
    "team.regeln.statistik.text" to "Over topplistene står summene for alle medlemmer i valgt periode: pumper, distanse og tid på foil, økter, runs og hvor mange medlemmer som var aktive.\nLag mot lag: i fellesskapet sammenligner laglistene alle godkjente lag med offentlige topplister, per nøkkeltall med summen av de beste 3, 5 eller 10 rytterne. Der gjelder samme mål for alle lag, ikke filtrene i deres egne lister.\nDen som er med i to lag, teller for begge.",
    "team.regeln.statistik.titel" to "Lagsummer",
    "team.regeln.titel" to "Lagregler",
    "team.regeln.was.text" to "En fast gruppe med egne topplister, arrangementer og lagchat.\nAlle kan starte lag, også flere, og være med i flere lag.\nEt nytt lag fungerer med en gang, via invitasjonslenker.",
    "team.regeln.was.titel" to "Hva er et lag?",
    "team.rolle.leiter" to "Leder",
    "team.rolle.mitglied" to "Medlem",
    "team.rolle.moderator" to "Moderator",
